        --fx-texture-opacity: 0.05;
    }

    [data-theme='phantom'] h1,
    [data-theme='phantom'] h2 {
        text-transform: uppercase;
        font-style: italic;
        letter-spacing: -0.01em;
    }

    /* Ticker: the faint rules of a ledger, and numerals that line up [TH68]. */
    [data-theme='ticker'] {
