        inset-inline-end: calc(var(--kp-space-sm, 0.5rem) + var(--kp-retro-close-room));
    }

    [data-theme='retro'] .kp-dialog__body {
        --kp-scrollbar-inset: 0px;
        --kp-scrollbar-ground: transparent;
        padding-inline-end: 20px;
    }

    /* The three windows whose only answer was that broken selector list.
       Square, as every window here is; their grounds stay the ones they were
       approved with. A menu is the popover's list and draws no bar of its
       own, a confirmation is a dialog and draws the dialog's, a toast
       never scrolls and draws none. */
    [data-theme='retro'] .kp-menu,
    [data-theme='retro'] .kp-confirm,
    [data-theme='retro'] .kp-toast {
        border-radius: 0;
    }

    [data-theme='retro'] :is(.kp-popover:not(.kp-tooltip), .kp-dialog:not(:has(> .kp-dialog__body)), .kp-dialog__body)::-webkit-scrollbar {
        display: none;
    }

    /* Enabled: ink arrows and the thumb. The thumb is at least eight pixels
       long, as the platform's is, and both lengths are whole pixels. */
    [data-theme='retro'] :is(.kp-popover:not(.kp-tooltip), .kp-dialog:not(:has(> .kp-dialog__body)), .kp-dialog__body)[data-kp-popover-overflowing] {
