        background-repeat: no-repeat;
        background-size:
            5px 5px,
            9px 9px,
            13px 13px;
        background-position:
            right bottom,
            right bottom,
            right bottom;
    }

    [data-theme='retro'] .kp-footer h4 {
        font-family: var(--theme-font-display);
        font-weight: 700;
    }

    [data-theme='retro'] .kp-footer a {
        color: var(--foreground);
        font-size: 0.85rem;
        text-decoration: underline;
        text-decoration-color: var(--border);
        text-underline-offset: 2px;
    }

    [data-theme='retro'] .kp-footer a:hover,
    [data-theme='retro'] .kp-footer a:focus-visible {
        background: var(--primary);
        color: var(--primary-foreground);
        text-decoration-color: transparent;
    }

    [data-theme='retro'] .kp-footer .microlabel {
        display: block;
        color: var(--foreground);
        padding: 0.1rem 0.6rem;
        border: 1px solid var(--border-strong);
        box-shadow: var(--kp-sunken);
    }

    [data-theme='retro'] .kp-footer .microlabel::before,
    [data-theme='retro'] .kp-footer .microlabel::after {
        content: none;
    }

    /* ── Badges, tags, status: sunken panels ───────────────────────────── */

    [data-theme='retro'] .kp-badge,
    [data-theme='retro'] .kp-tag {
        border-radius: 0;
        border: 1px solid var(--border-strong);
        box-shadow: var(--kp-sunken);
        font-family: var(--kp-dos);
        letter-spacing: 0.04em;
    }

    /* The badge's type size is the package's [scope-87]; the tag keeps this register's. */
    [data-theme='retro'] .kp-tag {
        font-size: 0.95rem;
    }

    [data-theme='retro'] .kp-health {
        font-family: var(--kp-dos);
        font-size: 1rem;
    }

    [data-theme='retro'] .kp-health__dot {
        border-radius: 0;
        box-shadow: var(--kp-raised);
    }

    /* The 50% dither of a control still loading. */
    [data-theme='retro'] .kp-skeleton {
        background-color: var(--card);
        background-image: var(--kp-brush);
        background-size: 2px 2px;
        image-rendering: pixelated;
        border-radius: 0;
    }

    /* The segmented progress bar of a 1995 installer. */
    [data-theme='retro'] .kp-progress {
        background: var(--popover);
        border: 1px solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-sunken);
        padding: 2px;
    }

    [data-theme='retro'] .kp-spinner {
        border-color: var(--border);
        border-top-color: var(--primary);
        border-radius: 0;
    }

    [data-theme='retro'] .kp-empty {
        border: 2px groove var(--border);
        border-radius: 0;
    }

    [data-theme='retro'] .kp-empty__title {
        font-family: var(--theme-font-display);
        font-weight: 700;
    }

    [data-theme='retro'] .kp-error {
        font-family: var(--kp-dos);
        font-size: 1rem;
        color: var(--destructive);
    }

    /* ── Text shapes: identifiers in the DOS face ──────────────────────── */

    [data-theme='retro'] .kp-id,
    [data-theme='retro'] .kp-url,
    [data-theme='retro'] .kp-numeric,
    [data-theme='retro'] .kp-timestamp,
    [data-theme='retro'] .kp-masked,
    [data-theme='retro'] .kp-copyable,
    [data-theme='retro'] .kp-truncate,
    [data-theme='retro'] .kp-cell-break,
    [data-theme='retro'] .kp-cell-truncate {
        font-family: var(--kp-dos);
        font-size: 1.05em;
        letter-spacing: 0.02em;
    }

    [data-theme='retro'] .kp-copyable__button {
        border: 1px solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-raised);
    }

    /* The copy button's two states win over this register's own button
       rules [gap-12]: those paint in kp.register, which beats the states
       in kp.components, so copied lost its success plate and a refused
       copy looked idle. Restated token for token. */
    [data-theme='retro'] .kp-copyable .kp-copyable__button[data-kp-copied] {
        border-color: var(--success);
        color: var(--success-foreground);
        background: var(--success);
    }

    [data-theme='retro'] .kp-copyable .kp-copyable__button[data-kp-copy-failed] {
        border-color: var(--destructive);
        border-style: dashed;
        color: var(--destructive);
    }

    /* ── Data: Explorer's column headers are buttons ───────────────────── */

    [data-theme='retro'] .kp-table {
        border-collapse: separate;
        border-spacing: 0;
        background: var(--popover);
    }

    [data-theme='retro'] .kp-table th {
        background: var(--card);
        /* The reach above a sticky header paints this ground too [fix-32]. */
        --kp-datatable-head-ground: var(--card);
        border: 1px solid var(--border-strong);
        box-shadow: var(--kp-raised);
        font-weight: 600;
    }

    /* A sticky header keeps its raised edge and, while its box is scrolled,
 * the reach above it [fix-32, scope-90]; at rest the raised edge alone. */
    [data-theme='retro'] .kp-datatable[data-kp-max-height][data-kp-scrolled] .kp-table thead th {
        box-shadow: var(--kp-raised), var(--kp-datatable-head-reach);
    }

    [data-theme='retro'] .kp-table td {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='retro'] .kp-table tbody tr:hover {
        background: var(--card);
    }

    [data-theme='retro'] .kp-datatable {
        border: 1px solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-sunken);
        background: var(--popover);
    }

    [data-theme='retro'] .kp-datatable__bar {
        background: var(--background);
        border-bottom: 1px solid var(--border);
    }

    [data-theme='retro'] .kp-datatable__sort[aria-sort] {
        color: var(--primary);
    }

    [data-theme='retro'] .kp-datatable__status,
    [data-theme='retro'] .kp-datatable__page {
        font-family: var(--kp-dos);
        font-size: 1rem;
    }

    [data-theme='retro'] .kp-diff {
        background: var(--popover);
        border: 1px solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-sunken);
    }

    [data-theme='retro'] .kp-diff__line {
        font-family: var(--kp-dos);
        font-size: 1.05em;
    }

    [data-theme='retro'] .kp-timeline {
        border-inline-start: 2px groove var(--border);
    }

    [data-theme='retro'] .kp-timeline__marker {
        background: var(--primary);
        border-radius: 0;
        box-shadow: var(--kp-raised-navy);
    }

    [data-theme='retro'] .kp-timeline__when {
        font-family: var(--kp-dos);
        font-size: 1rem;
        color: var(--muted-foreground);
    }

    [data-theme='retro'] .kp-tree {
        font-family: var(--kp-dos);
        font-size: 1.05rem;
    }

    /* The accordion [gap-12]: the plain system weight of its category toggle, bold once open. */
    [data-theme='retro'] .kp-accordion__summary {
        font-weight: 500;
    }

    [data-theme='retro'] .kp-accordion__summary::marker {
        color: var(--foreground);
    }

    [data-theme='retro'] .kp-accordion__item[open] > .kp-accordion__summary {
        font-weight: 700;
    }

    [data-theme='retro'] .kp-reorder {
        border: 1px solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-sunken);
        background: var(--popover);
    }

    /* ── Navigation and steps: the tab that lifts ──────────────────────── */

    /* 98.css's measured rule: the selected tab lifts two pixels and
       overhangs its neighbours by three. */
    [data-theme='retro'] .kp-tab {
        background: var(--background);
        color: var(--muted-foreground);
        border: 1px solid var(--border-strong);
        border-bottom: 0;
        border-radius: 0;
        box-shadow:
            inset 1px 1px 0 var(--popover),
            inset -1px 0 0 var(--border);
        padding-inline: 0.75rem;
    }

    [data-theme='retro'] .kp-tab[aria-selected='true'] {
        color: var(--foreground);
        font-weight: 600;
        margin-block-start: -2px;
        margin-inline-start: -3px;
        padding-inline: calc(0.75rem + 3px);
        position: relative;
        z-index: 2;
        background: var(--background);
    }

    [data-theme='retro'] .kp-tabs__list {
        border-bottom: 1px solid var(--border-strong);
        padding-inline-start: 0.4rem;
    }

    [data-theme='retro'] .kp-breadcrumb,
    [data-theme='retro'] .kp-pagination {
        font-family: var(--kp-dos);
    }

    [data-theme='retro'] .kp-pagination a[aria-current],
    [data-theme='retro'] .kp-pagination [aria-current] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: 0;
    }

    [data-theme='retro'] .kp-wizard {
        background: var(--background);
        border: 1px solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-raised);
    }

    [data-theme='retro'] .kp-wizard__steps {
        font-family: var(--kp-dos);
        font-size: 1.05rem;
    }

    /* ── Pickers and palettes ─────────────────────────────────────────── */

    [data-theme='retro'] .kp-datepicker__day[aria-selected='true'] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: 0;
    }

    [data-theme='retro'] .kp-datepicker__weekday,
    [data-theme='retro'] .kp-datepicker__title {
        font-family: var(--kp-dos);
        font-size: 1rem;
    }

    [data-theme='retro'] .kp-colorpicker__swatch {
        border: 1px solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-raised);
    }

    [data-theme='retro'] .kp-colorpicker__value {
        font-family: var(--kp-dos);
    }

    [data-theme='retro'] .kp-shortcuts__row kbd {
        font-family: var(--kp-dos);
        font-size: 1rem;
        border: 1px solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-raised);
        background: var(--card);
        display: inline-block;
        padding: 0 0.4em;
    }

    [data-theme='retro'] .kp-shortcuts__group-label,
    [data-theme='retro'] .kp-palette__group-label {
        font-family: var(--theme-font-display);
        font-weight: 700;
    }

    [data-theme='retro'] .kp-theme-menu__status,
    [data-theme='retro'] .kp-palette__status,
    [data-theme='retro'] .kp-combobox__status {
        font-family: var(--kp-dos);
        font-size: 1rem;
    }

    /* ── The roots the rules above reach only by their parts ──────────── */

    [data-theme='retro'] .kp-field {
        gap: var(--kp-space-xs);
    }

    [data-theme='retro'] .kp-form {
        gap: calc(var(--kp-space-lg) * 0.8);
    }

    [data-theme='retro'] .kp-combobox,
    [data-theme='retro'] .kp-datepicker,
    [data-theme='retro'] .kp-colorpicker,
    [data-theme='retro'] .kp-shortcuts,
    [data-theme='retro'] .kp-tabs {
        border-radius: 0;
    }

    /* ── Scrollbars: the 2×2 checkerboard track of 98.css ──────────────── */

    [data-theme='retro'] {
        scrollbar-color: var(--card) var(--popover);
    }

    [data-theme='retro'] ::-webkit-scrollbar {
        inline-size: 16px;
        block-size: 16px;
    }

    [data-theme='retro'] ::-webkit-scrollbar-track {
        background: conic-gradient(var(--popover) 0 25%, var(--card) 0 50%, var(--popover) 0 75%, var(--card) 0) 0 0 / 2px 2px;
        image-rendering: pixelated;
    }

    [data-theme='retro'] ::-webkit-scrollbar-thumb {
        background: var(--card);
        border: 1px solid var(--border-strong);
        box-shadow: var(--kp-raised);
    }

    /* ── The demo's own pieces [S46] ──────────────────────────────────── */

    /* The vertical margin note, in the DOS face. */
    [data-theme='retro'] .kp-side-note {
        position: absolute;
        inset-inline-end: 0.35rem;
        inset-block-start: 2rem;
        writing-mode: vertical-rl;
        font-family: var(--kp-dos);
        font-size: 1rem;
        letter-spacing: 0.18em;
        color: var(--muted-foreground);
    }

    /* Laurels: three sunken status panels, the way 1995 reported anything. */
    [data-theme='retro'] .kp-laurels {
        gap: 0.5rem;
        text-transform: uppercase;
        letter-spacing: 0.08em;
        font-size: 0.75rem;
        color: var(--muted-foreground);
    }

    [data-theme='retro'] .kp-laurels li {
        flex: 1 1 12rem;
        padding: 0.5rem 0.7rem;
        background: var(--background);
        border: 1px solid var(--border-strong);
        box-shadow: var(--kp-sunken);
    }

    [data-theme='retro'] .kp-laurels b {
        display: block;
        font-family: var(--theme-font-display);
        font-weight: 700;
        font-size: 1rem;
        letter-spacing: 0;
        text-transform: none;
        color: var(--foreground);
        margin-block-end: 0.15rem;
    }

    [data-theme='retro'] .kp-lede {
        max-width: 36rem;
        font-size: 1.05rem;
    }

    /* The platforms line: the DOS face, a teal block before every name. */
    [data-theme='retro'] .kp-platforms {
        margin-block-start: 1.6rem;
        gap: 0.2rem 1.4rem;
        font-family: var(--kp-dos);
        font-size: 1.05rem;
        letter-spacing: 0.06em;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    [data-theme='retro'] .kp-platforms span::before {
        content: '■ ';
        color: var(--accent);
    }

    /* The spec sheet: a Display Properties window — the ramp as its title
       bar, the raised chrome, the DOS face for the values. */
    [data-theme='retro'] .kp-spec {
        background: var(--background);
        color: var(--foreground);
        border: 1px solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-raised);
        padding: 3px;
        font-family: var(--kp-dos);
        font-size: 1.05rem;
        line-height: 1.5;
    }

    /* The swatches sit in the groove well the demo's fieldset draws. */
    [data-theme='retro'] .kp-spec dl {
        border: 2px groove var(--border);
        padding: 0.6rem 0.7rem;
        margin-block-start: 3px;
    }

    [data-theme='retro'] .kp-spec::before {
        content: '';
        display: block;
        block-size: 18px;
        background: var(--kp-ramp);
        margin-block-end: 0.6rem;
    }

    [data-theme='retro'] .kp-spec dl {
        margin: 0.2rem 0.7rem 0.6rem;
    }

    [data-theme='retro'] .kp-spec dt {
        color: var(--kp-teal-ink);
    }

    [data-theme='retro'] .kp-spec__swatch {
        border: 1px solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-raised);
        image-rendering: pixelated;
    }

    [data-theme='retro'] .kp-spec__font {
        font-family: var(--theme-font-display);
        font-weight: 700;
    }

    /* ── The arrival [S45, RT2]: the POST ─────────────────────────────── */

    /* The overlay js/effects.js builds when the theme answers the arrival
       hook with `boot`: the dictionary's boot line counting up in the DOS
       face on the deep ground, a raised Skip button, and the screen leaving
       through the pixel dissolve — four mask densities in discrete steps,
       once. Once per session; never under reduced motion (the module does
       not build it). */
    [data-theme='retro'] .kp-boot {
        position: fixed;
        inset: 0;
        z-index: var(--kp-z-boot, 100);
        background: var(--foreground);
        color: var(--background);
        font-family: var(--kp-dos);
        font-size: clamp(1rem, 2.2vw, 1.4rem);
        line-height: 1.35;
        padding: clamp(1rem, 4vw, 3rem);
        overflow: hidden;
        -webkit-mask-size: var(--kp-dither-cell) var(--kp-dither-cell);
        mask-size: var(--kp-dither-cell) var(--kp-dither-cell);
        image-rendering: pixelated;
    }

    [data-theme='retro'] .kp-boot__line {
        margin: 0;
        font: inherit;
        white-space: pre-wrap;
    }

    [data-theme='retro'] .kp-boot__skip {
        position: absolute;
        inset-inline-end: clamp(1rem, 4vw, 3rem);
        inset-block-end: clamp(1rem, 4vw, 3rem);
        font: inherit;
        color: var(--foreground);
        background: var(--card);
        border: 1px solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-raised);
        padding: 0.1rem 0.9rem;
        cursor: pointer;
    }

    [data-theme='retro'] .kp-boot__skip:active {
        box-shadow: var(--kp-pressed);
    }

    [data-theme='retro'] .kp-boot.is-off {
        pointer-events: none;
    }

    /* ── Motion, guarded [DI7] ────────────────────────────────────────── */

    /* Every animation and transition of this register lives here, inside
       the no-preference guard, so a reader who asked for reduced motion
       never receives one: the rest states above are what they get. The
       durations are literal because check-motion.mjs computes DI5's rate
       from them; the matching --kp-* knobs are what js/effects.js reads.
       Every step function is discrete on purpose: 1995 did not ease. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='retro'] [data-kp-reveal='headline'].is-dissolving::after {
            animation: kp-dither-clear 640ms steps(1, end) 1 forwards;
        }

        [data-theme='retro'] [data-kp-reveal='rule'].is-in::after {
            animation: kp-rule-in 480ms steps(12, end) 1 both;
        }

        /* The selection: the plate drags across the ink text in eight
           steps and returns to nothing as the element's own bar switches on
           — a size, not a colour, switched after the drag in no time (KT8:
           no mid-transition colour can be read); the ink turns white in the
           same instant. */
        [data-theme='retro'] mark.is-cleared::before {
            animation: kp-drag-select 360ms steps(8, end) 1;
        }

        [data-theme='retro'] mark {
            transition:
                background-size 0s linear 340ms,
                color 0s linear 340ms;
        }

        [data-theme='retro'] .kp-card[data-kp-reveal='emphasis'] mark.is-cleared::after {
            animation: kp-redact-lift 400ms steps(8, end) 1 both;
        }

        [data-theme='retro'] .kp-card[data-kp-reveal='emphasis'] mark.is-cleared:nth-of-type(2)::after {
            animation-delay: var(--kp-redact-stagger);
        }

        [data-theme='retro'] .kp-card[data-kp-reveal='emphasis'] mark.is-cleared:nth-of-type(3)::after {
            animation-delay: calc(2 * var(--kp-redact-stagger));
        }

        [data-theme='retro'] .kp-card[data-kp-reveal='emphasis'] mark {
            transition: color 0s linear 0s;
        }

        [data-theme='retro'] .kp-boot.is-off {
            animation: kp-dither-out 520ms steps(1, end) 1 forwards;
        }
    }

    /* ── Motion [DI5, DI7] ────────────────────────────────────────────── */

    /* Every keyframe here has its row in TIMINGS (js/effects.js); kp-rule-in
       is the base layer's. The dissolve only clears: four densities, then
       gone — one monotone change. */
    @keyframes kp-dither-clear {
        0% {
            opacity: 1;
            background-image: var(--kp-dd-100);
        }

        25% {
            opacity: 1;
            background-image: var(--kp-dd-75);
        }

        50% {
            opacity: 1;
            background-image: var(--kp-dd-50);
        }

        75% {
            opacity: 1;
            background-image: var(--kp-dd-25);
        }

        100% {
            opacity: 0;
            background-image: var(--kp-dd-25);
        }
    }

    @keyframes kp-dither-out {
        0% {
            opacity: 1;
            -webkit-mask-image: var(--kp-dm-100);
            mask-image: var(--kp-dm-100);
        }

        25% {
            opacity: 1;
            -webkit-mask-image: var(--kp-dm-75);
            mask-image: var(--kp-dm-75);
        }

        50% {
            opacity: 1;
            -webkit-mask-image: var(--kp-dm-50);
            mask-image: var(--kp-dm-50);
        }

        75% {
            opacity: 1;
            -webkit-mask-image: var(--kp-dm-25);
            mask-image: var(--kp-dm-25);
        }

        100% {
            opacity: 0;
            -webkit-mask-image: var(--kp-dm-25);
            mask-image: var(--kp-dm-25);
        }
    }

    @keyframes kp-drag-select {
        from {
            clip-path: inset(0 100% 0 0);
        }

        to {
            clip-path: inset(0 0 0 0);
        }
    }

    @keyframes kp-redact-lift {
        from {
            clip-path: inset(0 0 0 0);
        }

        to {
            clip-path: inset(0 0 0 100%);
        }
    }

    /* In the title bar the tag is white on the ramp, in the DOS face. */
    [data-theme='retro'] .kp-nav__brand-tag {
        font-family: var(--kp-dos);
        font-size: 0.95rem;
        letter-spacing: 0.08em;
        color: var(--primary-foreground);
        opacity: 0.9;
    }

    /* The segmented bar the POST counts along [S49, A11]: a sunken well
       with the blocks a memory test fills. The module writes
       --kp-boot-progress from 0 to 1; nothing here animates. */
    [data-theme='retro'] .kp-boot__bar {
        inline-size: min(22rem, 70vw);
        block-size: 18px;
        margin-block: 0.9rem 0.2rem;
        padding: 2px;
        background: var(--background);
        border: 1px solid var(--border-strong);
        box-shadow: var(--kp-sunken);
    }

    [data-theme='retro'] .kp-boot__bar::before {
        content: '';
        display: block;
        block-size: 100%;
        inline-size: calc(var(--kp-boot-progress, 0) * 100%);
        background-image: repeating-linear-gradient(90deg, var(--primary) 0 10px, transparent 10px 13px);
    }
    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — a pressed bevel, the same one its windows carry. */
    [data-theme='retro'] .kp-marquee {
        background: var(--card);
        border-block-start: 2px solid var(--background);
        border-block-end: 2px solid var(--border-strong);
        box-shadow: inset 0 2px 0 color-mix(in srgb, var(--foreground) 12%, transparent);
        font-family: var(--theme-font-mono);
        --kp-marquee: 36000ms;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    /* A mega menu's group headings speak in the caption's voice [scope-48]. */
    [data-theme='retro'] .kp-nav__menu[data-kp-menu-label]::before,
    [data-theme='retro'] .kp-nav__menu--wide .kp-nav__menu-heading {
        background: var(--secondary);
        font-family: var(--theme-font-mono);
        text-transform: none;
        border-block-end: 2px solid var(--border-strong);
    }

    /* ── The side navigation [feat-nav-3] ────────────────────────────
       Everything in this theme is a window on a desktop, and a column of
       links is the one part of that desktop that was always a list box:
       sunken, with the selection painted edge to edge.

       Its ground is the menu strip's (Kenny's retro notes, 2026-09-15,
       navigation.html#app-shell: "the sidebar should not be so dark, should
       be same as the top navbar"; #sidenav-over: "too dark"). It was
       `--input`, the 38% grey of a field's well, and the ink on it measured
       2.81:1 in firefox — a channel of 26 on a ground of 97, under the 4.5 of
       DI3 — where the bar's own ground, `--background`, carries the same ink
       at 9.46:1. */
    [data-theme='retro'] .kp-sidenav {
        --kp-sidenav-surface: var(--background);
        --kp-sidenav-list-pad: 0.15rem;
        --kp-sidenav-gap: 0;
        border: 2px solid;
        border-color: var(--border-strong) var(--border) var(--border) var(--border-strong);
    }

    [data-theme='retro'] .kp-sidenav__header {
        background: var(--primary);
        color: var(--primary-foreground);
        border-block-end: none;
        padding: 0.2rem 0.4rem;
    }

    [data-theme='retro'] .kp-sidenav__title {
        letter-spacing: 0;
        text-transform: none;
        color: inherit;
    }

    [data-theme='retro'] .kp-sidenav__link,
    [data-theme='retro'] .kp-sidenav__category-toggle {
        padding-inline: 0.7rem;
        font-weight: 500;
        border-radius: 0;
    }

    [data-theme='retro'] .kp-sidenav__link[aria-current='page'] {
        background: var(--primary);
        color: var(--primary-foreground);
    }

    /* ── Back to top, and a picture [feat-page-1, feat-media-1] ──────
       Everything on this desktop is bevelled, and a picture is an image
       control sunk into its dialog. */
    [data-theme='retro'] .kp-to-top {
        border: 2px solid;
        border-color: var(--background) var(--border-strong) var(--border-strong) var(--background);
        border-radius: 0;
    }

    [data-theme='retro'] .kp-media {
        border: 2px solid;
        border-color: var(--border-strong) var(--background) var(--background) var(--border-strong);
        border-radius: 0;
    }

    [data-theme='retro'] .kp-media-figure > figcaption {
        font-size: 0.75rem;
    }

    /* The figure carries the caption's voice, so the decision sits with
       the picture rather than with the words under it. */
    [data-theme='retro'] .kp-media-figure {
        color: var(--foreground);
    }

    /* ── The pressed state the register had been cancelling [fix-12] ───
       A layer beats a state: this register's hover background sits in
       kp.register, later than the kp.components rule that says what the
       button looks like while it is held down, so pressing it changed
       nothing.

       Not the base layer's values any more (Kenny, 2026-09-15 [scope-93]):
       this register's destructive button is a grey face with a dark-red
       label, and the base's pressed ground, --destructive-active, put that
       label on its own dark red — measured at 1.38:1.
       Pressed, the destructive button is what every other button here is:
       the same face with its bevel inverted and its label stepped a pixel
       (the pressed state under "Buttons" paints both), the label on the
       grey at the contrast it has at rest. */

    [data-theme='retro'] .kp-button--destructive:active:not(:disabled) {
        background-color: var(--card);
        border-color: var(--border-strong);
        color: var(--destructive);
    }

    /* ── The accelerator shows [gap-4, approved 2026-09-12] ────────────
       Windows 95 underlined one letter in every label — the accelerator —
       and showed it only once you held Alt. Touching a control does the
       same here: the underline appears under the marked letter.

       No movement, no colour, no shadow. That is precisely the feedback
       those desktops gave, and retro is the theme where the quotation is
       sharpest.

       It asks something of the consumer, and it is the only one of the six
       that does: the letter has to be marked, with `data-kp-key` on a span
       inside the label. A consumer who marks nothing sees nothing, which
       is the right failure — a theme may offer something that only works
       when you use it. */
    [data-theme='retro'] .kp-button [data-kp-key] {
        border-block-end: 1px solid transparent;
    }

    [data-theme='retro'] .kp-button:hover:not(:disabled) [data-kp-key],
    [data-theme='retro'] .kp-button:focus-visible [data-kp-key] {
        border-block-end-color: currentcolor;
    }

    /* ── …on every button [scope-80] ───────────────────────────────────
       Kenny approved the accelerator and asked for it on every button in
       this theme, not only on the ones whose consumer marked a letter. A
       label that marks nothing shows its first letter instead.

       Visual only. No key is bound and no `aria-keyshortcuts` is written:
       an underline that promised a shortcut which does nothing would be a
       lie to a keyboard user, and which letter is unique in a group, and
       whether Alt+letter may be taken from the browser, are open.

       `::first-letter` only reaches into a block container, and a button is
       an inline flex row whose text is an anonymous item, so a label of
       plain text is laid out as one line of text instead — the bargain
       components.css already makes for a marked label, and it looks the
       same: one line box, centred both ways. Only a label with no element
       inside it: an icon beside the text would be the "first letter"
       otherwise, so a button that carries an icon and marks nothing still
       shows none. The component's own `.kp-button__label` is answered the
       same way.

       …and beside an icon [scope-83]: Kenny, retro-accelerator "Alleen het
       teken" — the mark only, still no shortcut, and a button with an icon
       gets it too. CSS cannot tell a text node from the icon beside it, so
       such a label puts its text in `.kp-button__text`. In a flex row that
       element is an item, which is a block container, so `::first-letter`
       reaches it with no change of display; it has no rule in any other
       theme, where it lays out exactly as the bare text did. */
    [data-theme='retro'] .kp-button:not(:has(> *)),
    [data-theme='retro'] .kp-button__label:not(:has(> *)) {
        display: inline-block;
        align-content: center;
        text-align: center;
    }

    [data-theme='retro'] .kp-button:not(:has(> *))::first-letter,
    [data-theme='retro'] .kp-button__label:not(:has(> *))::first-letter,
    [data-theme='retro'] :is(.kp-button, .kp-button__label) > .kp-button__text:not(:has(> *))::first-letter {
        border-block-end: 1px solid transparent;
    }

    [data-theme='retro'] .kp-button:not(:has(> *)):is(:hover:not(:disabled), :focus-visible)::first-letter,
    [data-theme='retro'] .kp-button:is(:hover:not(:disabled), :focus-visible) > .kp-button__label:not(:has(> *))::first-letter,
    [data-theme='retro'] .kp-button:is(:hover:not(:disabled), :focus-visible) > .kp-button__text:not(:has(> *))::first-letter,
    [data-theme='retro'] .kp-button:is(:hover:not(:disabled), :focus-visible) > .kp-button__label > .kp-button__text:not(:has(> *))::first-letter {
        border-block-end-color: currentcolor;
    }

    /* ── Read-only fields [gap-11] ────────────────────────────────────── */

    /* A read-only field is a value on a record, not a box to type in. This
       register sets the field's border and ground in kp.register, which
       beats the read-only look in kp.components, so read-only painted like
       an editable field. The state is answered here, on top of the rest
       look, which stays as it was. */
    [data-theme='retro'] .kp-field__input[readonly] {
        border-style: dashed;
        background-color: var(--muted);
    }

    /* ── The palette's trigger in the bar [scope-48, scope-80] ─────────── */

    /* In the voice of this register's own nav links (Kenny, 2026-09-14,
       search-voice "Per thema"): the menu bar's plain words in a frame that
       is invisible until the item is pointed at, when it takes the primary
       selection. The link's typeface, case, spacing, shape and pointer
       answer are restated here, because the trigger is a button beside the
       list rather than a link in it. The underline a plain link carries is
       not: it says "this is a link", and the trigger is not one. */
    [data-theme='retro'] .kp-nav__search .kp-nav__search-trigger {
        padding-inline: 0.7rem;
        font-weight: 500;
        white-space: nowrap;
        border: 1px solid transparent;
        border-radius: 0;
        background: none;
        color: var(--foreground);
    }

    [data-theme='retro'] .kp-nav__search .kp-nav__search-trigger:hover,
    [data-theme='retro'] .kp-nav__search .kp-nav__search-trigger:focus-visible {
        background: var(--primary);
        color: var(--primary-foreground);
    }

    /* ── The pressed control's own face, hidden [retro notes 2026-09-15] ──
       Last in the file on purpose: every rule above that gives a button
       its ground uses the `background` shorthand, which resets
       `background-clip`, and a destructive or toast button pressed showed
       its own ground one pixel outside the face `::before` repaints. See
       the pressed state under "Buttons". */
    [data-theme='retro'] .kp-button:active:not(:disabled),
    [data-theme='retro'] .kp-icon-button:active:not(:disabled) {
        background-clip: text;
        border-image: linear-gradient(transparent, transparent) 1;
        box-shadow: none;
    }

    /* The call to action in the bar presses the same way [scope-93]. A
       pressed link has focus, so the menu strip's selection rule
       (`.kp-nav__links > li:focus-within > .kp-nav__link`, a heavier
       selector) paints its ground with the shorthand too; the doubled class
       outweighs it, so the face hidden here stays hidden. */
    [data-theme='retro'] .kp-nav__link.kp-nav__link--cta:active:active {
        background-clip: text;
        border-image: linear-gradient(transparent, transparent) 1;
        box-shadow: none;
    }

    /* ── The alarm [scope-94] ──────────────────────────────────────────────
       A 1995 error box: the desktop turns its teal, yellow hazard stripes top and bottom, and the words sit in a silver bevelled window whose title bar is the code line. Every colour is one of this theme's tokens. The
       button keeps this register's shape and takes the alarm's paint, on
       selectors long enough to outrank this register's own button states;
       the dialog takes no focus ring, because in the auto mode the whole
       screen is what has focus. */
    [data-theme='retro'] .kp-alarm {
        --kp-alarm-ground: hsl(from var(--accent) h s l / 0.94);
        --kp-alarm-ink: var(--destructive);
        --kp-alarm-soft: var(--foreground);
        --kp-alarm-split: var(--primary);
        --kp-alarm-on-ink: var(--destructive-foreground);
        --kp-alarm-glow: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-halo: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-scan: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-vignette: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-stripe: var(--warning);
        --kp-alarm-frame: 2px solid var(--background);
        --kp-alarm-panel-ground: var(--background);
        --kp-alarm-panel-border: 2px solid var(--foreground);
        --kp-alarm-panel-shadow:
            inset -2px -2px 0 hsl(from var(--foreground) h s l / 0.55), inset 2px 2px 0 hsl(from var(--background) h s 100),
            6px 6px 0 var(--foreground);
        --kp-alarm-panel-padding: 0 clamp(1rem, 3cqi, 2rem) clamp(1rem, 3cqi, 2rem);
        /* Kenny, 2026-09-16, rejecting the pixel face: "te grof om deftig te
           lezen". He picked the theme's own body face out of the demo
           [scope-108]; the window chrome around it carries the era, so the
           headline does not have to. */
        --kp-alarm-title-font: var(--theme-font-body);
        --kp-alarm-title-size: clamp(2rem, 8cqi, 6rem);
        --kp-alarm-title-tracking: 0.02em;
    }

    [data-theme='retro'] .kp-alarm:focus-visible {
        outline: none;
    }

    [data-theme='retro'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack,
    [data-theme='retro'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:hover:not(:disabled),
    [data-theme='retro'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:active:not(:disabled) {
        border-color: var(--kp-alarm-ink);
        background: var(--kp-alarm-ink);
        color: var(--kp-alarm-on-ink);
        text-shadow: none;
    }

    [data-theme='retro'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:is(:hover, :focus-visible):not(:disabled):not(:active) {
        background: var(--kp-alarm-on-ink);
        color: var(--kp-alarm-ink);
    }

    [data-theme='retro'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep,
    [data-theme='retro'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep:is(:hover, :focus-visible):not(:disabled) {
        border-color: currentColor;
        background: transparent;
        color: inherit;
        text-shadow: none;
    }

    [data-theme='retro'] .kp-alarm__panel {
        inline-size: min(100%, 48rem);
    }

    [data-theme='retro'] .kp-alarm__code {
        justify-self: stretch;
        margin-inline: calc(-1 * clamp(1rem, 3cqi, 2rem));
        padding: 0.3rem 0.6rem;
        background: var(--primary);
        color: var(--primary-foreground);
        letter-spacing: 0.04em;
        text-align: start;
    }
}

@layer kp.register {
    /* @kp-soft/themes — css/synthwave-register.css
   The synthwave register, 5.0.0 [S48, LIFT_PLAN row 1]: the horizon
   register. Scoped to [data-theme='synthwave'] and inert elsewhere;
   opt-in, imported after themes.css. The approved concept demo ("Outrun
   Horizon", 2026-09-08) is the reference for every value here, and
   docs/archive/RESEARCH_2026-09.md §25 is where each mechanism was measured.

   Cyberpunk is diagonal and day; synthwave is horizontal and night. What
   this file does, in order: the knobs and the texture; the type; the
   hooks of S45 — the chrome headline with its tracking wipe and shine,
   the neon tube that a <mark> switches on, the laser line under a
   heading, the horizon as divider; the hero's sky, sun and floor; the
   navbar; the buttons; the fields; and one answer per component root
   (TH124). The reveals have their rest state here and their motion in
   js/effects.js; without the script every one of them stands at rest.

   Colour discipline (DI9): nothing here names a colour. Every paint is a
   token or a relative colour of one. The neon rule of Synthwave '84 is
   kept throughout: the core of a glowing element is near-white and the
   colour lives in its shadow, so every core passes contrast on its own.

   Nothing here flickers. The references' CRT flicker (133/s) and the sun
   that snaps once a second were measured and refused (DI5); the floor
   drifts one cell per six seconds and never changes luminance. */

    [data-theme='synthwave'] {
        /* The configuration surface [AR43], the demo's values as defaults. */
        --kp-nav-enter: 520ms;
        --kp-nav-enter-delay: 80ms;
        --kp-reveal-threshold: 0.6;
        --kp-reveal-stagger: 420ms;
        --kp-redact-stagger: 160ms;
        --kp-classified-delay: 900ms;
        --kp-wipe: 720ms;
        --kp-rule-draw: 900ms;
        --kp-rule-weight: 2px;
        --kp-tracking: 700ms;
        --kp-shine: 1400ms;
        --kp-tube-on: 1100ms;
        --kp-sun-cut: 360ms;
        --kp-floor-drift: 6s;
        --kp-floor-cell: 7vw 6vw;
        --kp-horizon-height: 56px;
        --kp-sun-size: min(38vmin, 340px);
        --kp-boot: 550ms;
        /* The reveals this theme performs [S45]: js/effects.js reads these
           and leaves a theme that declares none at rest. */
        --kp-reveal-headline: tracking;
        --kp-reveal-emphasis: tube;
        --kp-reveal-rule: laser;
        --kp-arrival: boot;
        /* The OSD face for labels, identifiers and timestamps is the theme's
           mono token (VT323); the data face is Share Tech Mono, under Q1's
           name. */
        --kp-osd: var(--theme-font-mono);
        --kp-mono: 'KP Tech Mono', 'Share Tech Mono', 'JetBrains Mono', ui-monospace, Menlo, monospace;
        /* The pink that reads as text: the hero's second ink, 8.9:1 on the
           void and 6.9:1 on the tape (the reference pink fails at 4.34). */
        --kp-pink-text: var(--surface-hero-fg-2);
        --kp-hairline: hsl(from var(--kp-pink-text) h s l / 0.25);
        /* The neon rest stacks (Synthwave '84): a near-white core, the
           colour in the shadow. */
        --kp-tube-pink:
            0 0 2px var(--sidebar-background), 0 0 6px hsl(from var(--primary) h s l / 0.7), 0 0 14px hsl(from var(--primary) h s l / 0.55),
            0 0 28px hsl(from var(--primary) h s l / 0.3);
        --kp-tube-cyan:
            0 0 2px var(--sidebar-background), 0 0 4px hsl(from var(--accent) h s l / 0.8), 0 0 10px hsl(from var(--accent) h s l / 0.5),
            0 0 22px hsl(from var(--accent) h s l / 0.3);
        --kp-tube-laser: 0 0 2px var(--sidebar-background), 0 0 8px hsl(from var(--warning-foreground) h s l / 0.6);
        --kp-core: hsl(from var(--foreground) h 20% 98%);
        /* The stripe of the '84 active tab: pink to cyan, 4px. */
        --kp-stripe: linear-gradient(to right, var(--primary), var(--accent));
        /* The sky, the sun and the chrome, derived from the tokens. Every
           stop of the sky is dark enough for lavender text (4.5:1 and up),
           because the hero's ground is measured on the rendered page. */
        --kp-sky-1: hsl(from var(--surface-hero-bg) calc(h - 26) 69% 15%);
        --kp-sky-2: hsl(from var(--surface-hero-bg) calc(h + 22) 68% 22%);
        --kp-sky-3: hsl(from var(--primary) h 65% 32%);
        --kp-sun-top: hsl(from var(--warning-foreground) calc(h - 5) s calc(l - 9));
        --kp-sun-bottom: hsl(from var(--primary) calc(h - 34) s l);
        --kp-sun-glow: hsl(from var(--destructive) h 95% 52%);
        --kp-grid: hsl(from var(--kp-pink-text) h s l / 0.55);
        --kp-chrome-1: hsl(from var(--accent) 205 65% 48%);
        --kp-chrome-2: hsl(from var(--foreground) 205 40% 88%);
        --kp-chrome-3: hsl(from var(--primary) 330 43% 24%);
        --kp-chrome-4: hsl(from var(--primary) 330 38% 54%);

        /* The texture [DI9, AR46]: a static VHS screen-door — a 2px row
           raster and a 3px RGB stripe (nightride.fm's overlay) — at DI9's
           ceiling and not a hair over. It never moves. */
        --fx-texture:
            linear-gradient(hsl(from var(--sidebar-background) h s l / 0) 50%, hsl(from var(--sidebar-background) h s l / 0.06) 50%),
            linear-gradient(
                90deg,
                hsl(from var(--destructive) h s l / 0.03),
                hsl(from var(--success-foreground) h s l / 0.01),
                hsl(from var(--chart-4) h s l / 0.03)
            );
        --fx-texture-size: 100% 2px, 3px 100%;
        --fx-texture-opacity: 1;
    }

    /* ── Type ──────────────────────────────────────────────────────────── */

    [data-theme='synthwave'] h1,
    [data-theme='synthwave'] h2,
    [data-theme='synthwave'] h3 {
        font-family: var(--theme-font-display);
        text-transform: uppercase;
        letter-spacing: 0.08em;
    }

    /* Microlabels: the OSD face, pink, with the tape prefix. */
    [data-theme='synthwave'] .microlabel {
        font-family: var(--kp-osd);
        font-size: 1rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--kp-pink-text);
        line-height: 1;
    }

    [data-theme='synthwave'] .microlabel::before {
        content: '▶ ';
        color: var(--accent);
    }

    /* ── The hooks [S45]: the heading accent, the mark, the rule, the divider ── */

    /* The heading accent: a display headline at the display step (S47),
       in chrome — the 50/51 break of the genre's title treatment, a
       stroke of near-white, an extrusion below. */
    [data-theme='synthwave'] [data-kp-surface] h1 {
        font-weight: 900;
        letter-spacing: 0.06em;
        margin-block: 0 0.4em;
        text-wrap: balance;
        position: relative;
        background: linear-gradient(
            180deg,
            var(--kp-chrome-1) 0%,
            var(--kp-chrome-2) 50%,
            var(--kp-chrome-3) 51%,
            var(--kp-chrome-4) 55%,
            var(--kp-chrome-3) 59%,
            var(--kp-chrome-4) 65%,
            var(--kp-chrome-4) 75%,
            var(--kp-core) 100%
        );
        -webkit-background-clip: text;
        background-clip: text;
        -webkit-text-fill-color: transparent;
        -webkit-text-stroke: 1px hsl(from var(--kp-core) h s l / 0.35);
        filter: drop-shadow(0 2px 0 hsl(from var(--kp-chrome-1) h s l / 0.6)) drop-shadow(0 4px 12px hsl(from var(--sidebar-background) h s l / 0.5));
    }

    /* A section heading is a cyan tube: near-white core, cyan glow. */
    [data-theme='synthwave'] [data-kp-surface] h2 {
        font-weight: 700;
        color: var(--kp-core);
        text-shadow: var(--kp-tube-cyan);
    }

    [data-theme='synthwave'] [data-kp-reveal='headline'] {
        position: relative;
    }

    /* The headline reveal: one tracking wipe (a band of the text slides
       sideways with an RGB fringe, six steps, once — a VHS head losing the
       picture for a beat), then one shine across the chrome. The copies
       read `data-kp-text`, which the effects module writes. */
    [data-theme='synthwave'] [data-kp-reveal='headline']::before,
    [data-theme='synthwave'] [data-kp-reveal='headline']::after {
        content: attr(data-kp-text);
        position: absolute;
        inset: 0;
        opacity: 0;
        pointer-events: none;
        white-space: pre-wrap;
    }

    [data-theme='synthwave'] [data-kp-reveal='headline']::before {
        -webkit-text-fill-color: var(--kp-core);
        text-shadow:
            2px 0 hsl(from var(--chart-4) h s l / 0.5),
            -2px 0 hsl(from var(--primary) h s l / 0.35);
    }

    [data-theme='synthwave'] [data-kp-reveal='headline']::after {
        opacity: 1;
        background: linear-gradient(225deg, transparent 47%, hsl(from var(--kp-core) h s l / 0.85) 50%, transparent 53%);
        background-size: 400% 400%;
        background-position: 100% 100%;
        -webkit-background-clip: text;
        background-clip: text;
        -webkit-text-fill-color: transparent;
    }

    /* The laser line under a section heading draws from the centre
       outward when the heading enters the viewport (C3). Without the
       script — no data-kp-effects on the root — it stands drawn. */
    [data-theme='synthwave'] [data-kp-reveal='rule']::after {
        content: '';
        display: block;
        height: var(--kp-rule-weight);
        margin-top: 0.5rem;
        background: linear-gradient(to right, transparent, var(--warning-foreground) 20%, var(--warning-foreground) 80%, transparent);
        box-shadow: 0 0 8px hsl(from var(--warning-foreground) h s l / 0.6);
        transform-origin: center;
    }

    [data-theme='synthwave'][data-kp-effects] [data-kp-reveal='rule']:not(.is-in)::after {
        transform: scaleX(0);
    }

    /* The mark: emphasis is a neon tube. At rest it is on — near-white
       core, pink glow. With the script armed it is dark glass until the
       module switches it on, one after another, with two dips on the way
       with one dip on the way (2.7/s, under DI5's three). */
    [data-theme='synthwave'] mark {
        background: none;
        color: var(--kp-core);
        font-weight: 700;
        white-space: nowrap;
        text-shadow: var(--kp-tube-pink);
    }

    [data-theme='synthwave'][data-kp-effects] mark:not(.is-cleared) {
        color: hsl(from var(--foreground) h s l / 0.4);
        text-shadow: none;
    }

    /* The divider: the horizon [TH121]. A magenta line with its triple
       glow across the top, and a short grid ramp receding under it: rows
       spaced by the square rule, verticals converging on the centre. */
    [data-theme='synthwave'] [data-kp-divider] {
        display: block;
        position: relative;
        block-size: var(--kp-horizon-height);
        background: var(--background);
        overflow: hidden;
        isolation: isolate;
    }

    [data-theme='synthwave'] [data-kp-divider]::before {
        content: '';
        position: absolute;
        inset: 10px 0 auto;
        height: 2px;
        background: var(--kp-pink-text);
        box-shadow:
            0 0 12px var(--primary),
            0 0 32px hsl(from var(--primary) h s l / 0.6),
            0 -6px 40px hsl(from var(--accent) h s l / 0.35);
        z-index: 1;
    }

    [data-theme='synthwave'] [data-kp-divider]::after {
        content: '';
        position: absolute;
        inset: 12px -30% 0;
        background:
            repeating-linear-gradient(to bottom, var(--kp-grid) 0 1px, transparent 1px 9px),
            repeating-linear-gradient(to right, var(--kp-grid) 0 1px, transparent 1px 120px);
        transform-origin: 50% 0;
        transform: perspective(90px) rotateX(58deg);
        opacity: 0.6;
        mask-image: linear-gradient(to bottom, hsl(from var(--sidebar-background) h s l) 0, transparent 100%);
    }

    [data-theme='synthwave'] [data-kp-surface='app'] + [data-kp-divider] {
        background: var(--sidebar-background);
    }

    /* ── The hero: the sky, the sun, the floor ────────────────────────── */

    /* The section's own ground is the sky ramp with every stop dark; the
       sun and the floor are pseudo-elements, so the ground a text is
       measured against stays the ramp. The two-colour inset vignette of
       the reference sits on the section. */
    [data-theme='synthwave'] [data-kp-surface='hero'] {
        position: relative;
        overflow: hidden;
        isolation: isolate;
        padding-block: 3.2rem 5rem;
        background: linear-gradient(
            to bottom,
            var(--background) 0,
            var(--kp-sky-1) 22%,
            var(--kp-sky-2) 45%,
            var(--kp-sky-3) 62%,
            var(--kp-sky-1) 66%,
            var(--surface-hero-bg) 100%
        );
        box-shadow:
            inset 0 0 50px 1px hsl(from var(--accent) h s l / 0.22),
            inset 0 0 120px 1px hsl(from var(--kp-sun-bottom) h s l / 0.35);
    }

    /* The sun: a disc from amber to magenta, cut by a mask whose bands
       follow Argyle's rule (band n = n%, gap = (8 − n)%), static. */
    [data-theme='synthwave'] [data-kp-surface='hero']::before {
        content: '';
        position: absolute;
        left: 60%;
        top: 4%;
        width: var(--kp-sun-size);
        aspect-ratio: 1;
        translate: -50% 0;
        border-radius: 50%;
        background: linear-gradient(var(--kp-sun-top), var(--kp-sun-bottom));
        filter: drop-shadow(0 0 1.5rem var(--kp-sun-glow));
        mask-image: linear-gradient(
            to top,
            var(--sidebar-background) 1%,
            0%,
            transparent 8%,
            0%,
            var(--sidebar-background) 10%,
            0%,
            transparent 16%,
            0%,
            var(--sidebar-background) 19%,
            0%,
            transparent 24%,
            0%,
            var(--sidebar-background) 28%,
            0%,
            transparent 32%,
            0%,
            var(--sidebar-background) 37%,
            0%,
            transparent 40%,
            0%,
            var(--sidebar-background) 46%,
            0%,
            transparent 48%,
            0%,
            var(--sidebar-background) 55%,
            0%,
            transparent 56%,
            0%,
            var(--sidebar-background) 57%
        );
        z-index: -2;
        pointer-events: none;
    }

    /* The floor: a conic-gradient grid under rotateX with the three
       horizon glows; it drifts one cell per six seconds, seamless, and
       fades before it reaches the text. */
    [data-theme='synthwave'] [data-kp-surface='hero']::after {
        content: '';
        position: absolute;
        left: -30%;
        right: -30%;
        top: 70%;
        height: 60%;
        background: conic-gradient(from 90deg at 1px 1px, transparent 90deg, var(--kp-grid) 0) 0 0 / var(--kp-floor-cell);
        transform-origin: 50% 0;
        transform: perspective(60vh) rotateX(74deg);
        border-top: 1px solid var(--kp-pink-text);
        box-shadow:
            0 -40px 60px hsl(from var(--kp-pink-text) h s l / 0.35),
            -70px -60px 80px hsl(from var(--accent) h s l / 0.18),
            70px -60px 80px hsl(from var(--accent) h s l / 0.18);
        mask-image: linear-gradient(to bottom, var(--sidebar-background) 0, var(--sidebar-background) 60%, transparent);
        z-index: -1;
        pointer-events: none;
    }

    [data-theme='synthwave'] [data-kp-surface='hero'] [data-kp-hero-grid] {
        grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
        gap: 3rem;
        align-items: end;
    }

    @container (max-width: 52rem) {
        [data-theme='synthwave'] [data-kp-surface='hero'] [data-kp-hero-grid] {
            grid-template-columns: 1fr;
        }
    }

    /* ── The navbar: a flat bar, the stripe under the active item ─────── */

    [data-theme='synthwave'] .kp-nav-wrap {
        background: var(--background);
    }

    [data-theme='synthwave'] .kp-nav {
        background: var(--background);
        border-bottom: 1px solid hsl(from var(--foreground) h s l / 0.08);
        padding-block: calc(var(--kp-nav-pad-block, 1.1rem) * var(--kp-nav-pad-scale, 1))
            calc(var(--kp-nav-pad-block, 0px) * var(--kp-nav-pad-scale, 1));
        position: relative;
        /* Its own stacking context for the bar's decorations; the layer is the
         * wrapper's, from the base [scope-48]. */
        isolation: isolate;
    }

    /* The brand in small chrome. */
    [data-theme='synthwave'] .kp-nav__brand {
        font-family: var(--theme-font-display);
        font-weight: 900;
        font-size: 1.5rem;
        letter-spacing: 0.08em;
        line-height: 1;
        text-transform: uppercase;
        text-decoration: none;
        padding-bottom: 0.9rem;
        background: linear-gradient(
            180deg,
            var(--kp-core) 0%,
            var(--kp-chrome-2) 50%,
            var(--kp-chrome-3) 51%,
            var(--kp-chrome-4) 60%,
            var(--kp-core) 100%
        );
        -webkit-background-clip: text;
        background-clip: text;
        -webkit-text-fill-color: transparent;
    }

    [data-theme='synthwave'] .kp-nav__links {
        gap: 0;
    }

    [data-theme='synthwave'] .kp-nav__link {
        display: block;
        padding-inline: 1.1rem;
        font-weight: 600;
        letter-spacing: 0.18em;
        text-transform: uppercase;
        color: var(--foreground);
        text-decoration: none;
        position: relative;
        border-radius: 0;
    }

    /* The 4px pink→cyan stripe of Synthwave '84's active tab, with its
       underglow, on the current item and on hover. */
    [data-theme='synthwave'] .kp-nav__link::after {
        content: '';
        position: absolute;
        left: 0.6rem;
        right: 0.6rem;
        bottom: 0;
        height: 4px;
        background: var(--kp-stripe);
        transform: scaleX(0);
        transform-origin: left center;
    }

    [data-theme='synthwave'] .kp-nav__link:hover,
    [data-theme='synthwave'] .kp-nav__link:focus-visible,
    [data-theme='synthwave'] .kp-nav__link[aria-current],
    [data-theme='synthwave'] .kp-nav__links > li:focus-within > .kp-nav__link {
        color: var(--kp-core);
        background: none;
        box-shadow: inset 0 -5px 25px hsl(from var(--primary) h s l / 0.15);
    }

    /* The keyboard keeps its ring [fix-38, DI2]: the glow above replaced
       the inner half on a focused link, and the outer half is the page's
       own ground, so a Tab showed only the stripe under the word. The ring
       is restated beside the glow. */
    [data-theme='synthwave'] .kp-nav__links > li > .kp-nav__link:focus-visible {
        box-shadow:
            0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring),
            inset 0 -5px 25px hsl(from var(--primary) h s l / 0.15);
    }

    [data-theme='synthwave'] .kp-nav__link:hover::after,
    [data-theme='synthwave'] .kp-nav__link:focus-visible::after,
    [data-theme='synthwave'] .kp-nav__link[aria-current]::after,
    [data-theme='synthwave'] .kp-nav__links > li:focus-within > .kp-nav__link::after {
        transform: scaleX(1);
    }

    [data-theme='synthwave'] .kp-nav__link[aria-haspopup]::before {
        content: '▾ ';
        color: var(--accent);
    }

    [data-theme='synthwave'] .kp-nav__link--lang {
        border-left: 1px solid hsl(from var(--foreground) h s l / 0.18);
        margin-left: 0.4rem;
    }

    /* The call to action is a neon frame. */
    [data-theme='synthwave'] .kp-nav__link--cta {
        margin-left: 0.6rem;
        padding-inline: 1.3rem;
        border: 2px solid var(--primary);
        border-radius: var(--radius);
        color: var(--kp-core);
        text-shadow: var(--kp-tube-pink);
        box-shadow:
            inset 0 0 0.5em 0 hsl(from var(--primary) h s l / 0.35),
            0 0 0.5em 0 hsl(from var(--primary) h s l / 0.35);
        align-self: center;
    }

    [data-theme='synthwave'] .kp-nav__link--cta::after {
        display: none;
    }

    [data-theme='synthwave'] .kp-nav__link--cta:hover {
        box-shadow:
            inset 0 0 0.7em 0 hsl(from var(--primary) h s l / 0.55),
            0 0 1.4em 0 hsl(from var(--primary) h s l / 0.55);
    }

    /* The dropdown: a tape panel with the stripe on top, ▶ before every item. */
    [data-theme='synthwave'] .kp-nav__menu {
        background: var(--card);
        border: 1px solid var(--kp-hairline);
        border-top: 4px solid transparent;
        border-image: var(--kp-stripe) 1;
        border-radius: 0;
        padding: 0.5rem 0;
        min-width: 13rem;
        box-shadow: 0 12px 40px hsl(from var(--sidebar-background) h s l / 0.6);
    }

    /* Collapsed, the dropdown is a list in the flow, not a panel [gap-12]:
       the rule above dresses the floating panel in kp.register, which
       beats the reset in kp.components, so the reset is restated here. */
    @container kp-nav (max-width: 40rem) {
        [data-theme='synthwave'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open] .kp-nav__menu {
            min-width: 0;
            padding-inline-start: var(--kp-nav-menu-indent, 1rem);
            border: 0;
            background: transparent;
            box-shadow: none;
        }
    }

    [data-theme='synthwave'] .kp-nav__menu a {
        display: block;
        padding-inline: 1rem;
        letter-spacing: 0.14em;
        text-transform: uppercase;
        color: var(--foreground);
        text-decoration: none;
    }

    [data-theme='synthwave'] .kp-nav__menu a::before {
        content: '▶ ';
        color: var(--accent);
        font-family: var(--kp-osd);
    }

    [data-theme='synthwave'] .kp-nav__menu a:hover,
    [data-theme='synthwave'] .kp-nav__menu a:focus-visible {
        color: var(--kp-core);
        background: var(--popover);
        text-shadow: var(--kp-tube-pink);
    }

    /* ── Buttons: square, a 2px neon frame, the sun cut on hover ──────── */

    [data-theme='synthwave'] .kp-button {
        --kp-frame: var(--primary);
        --kp-glow: hsl(from var(--primary) h s l / 0.45);
        position: relative;
        padding-inline: 1.8rem;
        font-weight: 700;
        font-size: 0.95rem;
        letter-spacing: 0.16em;
        text-transform: uppercase;
        color: var(--kp-core);
        background: transparent;
        border: 2px solid var(--kp-frame);
        border-radius: var(--radius);
        isolation: isolate;
        text-shadow: var(--kp-tube-pink);
        box-shadow:
            inset 0 0 0.5em 0 var(--kp-glow),
            0 0 0.5em 0 var(--kp-glow);
    }

    [data-theme='synthwave'] .kp-button:hover {
        background: transparent;
        box-shadow:
            inset 0 0 0.7em 0 var(--kp-glow),
            0 0 1.6em 0 var(--kp-glow);
        transform: translateY(-1px);
    }

    [data-theme='synthwave'] .kp-button:active {
        transform: translateY(1px);
    }

    /* The demo's call-to-action row: wide buttons, as in the reference. A
       pager's or a menu's button keeps its own width (DI11 at 320 px). */
    [data-theme='synthwave'] [data-kp-surface='hero'] .kp-row > .kp-button {
        min-width: 13rem;
    }

    /* The focus ring lives inside the frame, two channels, inset, so the
       glow below never covers a half of it (AR30, DI2). */
    [data-theme='synthwave'] .kp-button:focus-visible {
        outline: none;
        box-shadow:
            inset 0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring),
            inset 0 0 0 calc(var(--kp-focus-ring-inner-width, 2px) + 2px) var(--focus-ring-contrast);
    }

    /* The sun cut: two horizontal slits in the ground's colour cross the
       button once on hover — the sun's stripes, borrowed for a beat. */
    [data-theme='synthwave'] .kp-button::before,
    [data-theme='synthwave'] .kp-button::after {
        content: '';
        position: absolute;
        left: -4px;
        right: -4px;
        height: 3px;
        background: var(--background);
        opacity: 0;
        pointer-events: none;
    }

    [data-theme='synthwave'] .kp-button::before {
        top: 34%;
    }

    [data-theme='synthwave'] .kp-button::after {
        top: 58%;
    }

    [data-theme='synthwave'] .kp-card .kp-button::before,
    [data-theme='synthwave'] .kp-card .kp-button::after {
        background: var(--card);
    }

    [data-theme='synthwave'] .kp-button--primary {
        background: var(--primary);
        color: var(--primary-foreground);
        text-shadow: none;
    }

    [data-theme='synthwave'] .kp-button--primary:hover {
        background: hsl(from var(--primary) h s calc(l + 6));
    }

    [data-theme='synthwave'] .kp-button--destructive {
        --kp-frame: var(--destructive);
        --kp-glow: hsl(from var(--destructive) h s l / 0.4);
        background: transparent;
        color: var(--kp-core);
        text-shadow:
            0 0 2px var(--sidebar-background),
            0 0 8px hsl(from var(--destructive) h s l / 0.6);
    }

    [data-theme='synthwave'] .kp-button--ghost {
        --kp-frame: transparent;
        box-shadow: none;
    }

    [data-theme='synthwave'] .kp-button--ghost:hover {
        --kp-frame: var(--kp-hairline);
    }

    [data-theme='synthwave'] .kp-button:disabled {
        opacity: 0.45;
        transform: none;
    }

    [data-theme='synthwave'] .kp-button--sm {
        min-width: 0;
        padding-inline: 1rem;
    }

    [data-theme='synthwave'] .kp-icon-button {
        border: 2px solid var(--kp-hairline);
        border-radius: var(--radius);
        color: var(--accent);
    }

    [data-theme='synthwave'] .kp-icon-button:hover {
        border-color: var(--accent);
        box-shadow: 0 0 0.6em hsl(from var(--accent) h s l / 0.4);
    }

    /* ── Fields ───────────────────────────────────────────────────────── */

    [data-theme='synthwave'] .kp-field__label {
        font-family: var(--kp-osd);
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--kp-pink-text);
    }

    [data-theme='synthwave'] .kp-field__label::before {
        content: '▶ ';
        color: var(--accent);
    }

    [data-theme='synthwave'] .kp-field__input {
        font-weight: 500;
        background: var(--sidebar-background);
        border: 2px solid hsl(from var(--kp-pink-text) h s l / 0.35);
        border-radius: var(--radius);
        padding-inline: 0.9rem;
        caret-color: var(--accent);
    }

    [data-theme='synthwave'] .kp-field__input:focus-visible {
        outline: none;
        border-color: var(--accent);
        box-shadow:
            0 0 0 1px var(--accent),
            0 0 14px hsl(from var(--accent) h s l / 0.35);
    }

    [data-theme='synthwave'] select.kp-field__input::picker-icon {
        color: var(--accent);
    }

    [data-theme='synthwave'] .kp-field__help {
        font-family: var(--kp-osd);
        letter-spacing: 0.06em;
    }

    [data-theme='synthwave'] .kp-field--invalid .kp-field__input {
        border-color: var(--warning-foreground);
        box-shadow: 0 0 0 1px var(--warning-foreground);
    }

    [data-theme='synthwave'] .kp-field__error {
        font-family: var(--kp-osd);
        color: var(--warning-foreground);
    }

    [data-theme='synthwave'] .kp-field__error::before {
        content: '!! ';
    }

    [data-theme='synthwave'] .kp-field__check {
        border: 2px solid var(--primary);
        border-radius: var(--radius);
        background: var(--sidebar-background);
        box-shadow: 0 0 6px hsl(from var(--primary) h s l / 0.4);
    }

    [data-theme='synthwave'] .kp-field__check:checked {
        background: var(--sidebar-background);
        border-color: var(--primary);
        box-shadow:
            inset 0 0 0 3px var(--sidebar-background),
            inset 0 0 0 8px var(--accent),
            0 0 8px var(--accent);
    }

    [data-theme='synthwave'] .kp-fieldset {
        border: 1px solid var(--kp-hairline);
        border-radius: var(--radius);
    }

    /* The switch [gap-11], in the checkbox's voice: the theme's radius on a
       primary-edged track over the sidebar's night with a faint glow, and
       a thumb that lights in the accent with its own glow once on. */
    [data-theme='synthwave'] .kp-switch {
        --kp-switch-radius: var(--radius);
        --kp-switch-border: 2px;
    }

    [data-theme='synthwave'] .kp-switch__input {
        border: 2px solid var(--primary);
        background: var(--sidebar-background);
        box-shadow: 0 0 6px hsl(from var(--primary) h s l / 0.4);
    }

    [data-theme='synthwave'] .kp-switch__input:checked {
        background: var(--sidebar-background);
        border-color: var(--primary);
    }

    [data-theme='synthwave'] .kp-switch__input:checked::before {
        background: var(--accent);
        box-shadow: 0 0 8px var(--accent);
    }

    [data-theme='synthwave'] .kp-form__summary {
        border-left: 4px solid transparent;
        border-image: var(--kp-stripe) 1;
        background: var(--card);
    }

    /* ── Cards, surfaces and containers: the tape with the stripe ─────── */

    [data-theme='synthwave'] .kp-card {
        background: var(--card);
        border: 1px solid var(--kp-hairline);
        border-top: 4px solid transparent;
        border-image: var(--kp-stripe) 1;
        border-radius: 0;
        box-shadow: 0 0 40px hsl(from var(--sidebar-background) h s l / 0.6);
    }

    [data-theme='synthwave'] .kp-card__title {
        font-family: var(--theme-font-display);
        font-weight: 700;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        color: var(--kp-core);
        text-shadow: var(--kp-tube-pink);
    }

    /* The dossier: a tape card; the label is the OSD's REC stamp; the
       redactions are tracking noise that clears when the file is opened. */
    [data-theme='synthwave'] .kp-card[data-kp-reveal='emphasis'] {
        position: relative;
    }

    [data-theme='synthwave'] .kp-card[data-kp-label]::before {
        content: '● ' attr(data-kp-label);
        position: absolute;
        top: 0.9rem;
        right: 1.4rem;
        font-family: var(--kp-osd);
        font-size: 1rem;
        letter-spacing: 0.2em;
        text-transform: uppercase;
        color: var(--kp-pink-text);
    }

    [data-theme='synthwave'] .kp-card[data-kp-reveal='emphasis'] mark {
        position: relative;
    }

    [data-theme='synthwave'] .kp-card[data-kp-reveal='emphasis'] mark::after {
        content: '';
        position: absolute;
        inset: -0.05em -0.15em;
        background: repeating-linear-gradient(90deg, var(--primary) 0 2px, var(--card) 2px 3px, var(--accent) 3px 4px, var(--card) 4px 7px);
        opacity: 0.9;
        transform: scaleX(0);
        transform-origin: right center;
    }

    [data-theme='synthwave'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:not(.is-cleared)::after {
        transform: scaleX(1);
    }

    [data-theme='synthwave'] .kp-card[data-kp-reveal='emphasis'] mark.is-cleared {
        text-shadow: var(--kp-tube-cyan);
    }

    [data-theme='synthwave'] .kp-dialog,
    [data-theme='synthwave'] .kp-popover,
    [data-theme='synthwave'] .kp-menu,
    [data-theme='synthwave'] .kp-toast,
    [data-theme='synthwave'] .kp-tooltip,
    [data-theme='synthwave'] .kp-confirm,
    [data-theme='synthwave'] .kp-datepicker__panel,
    [data-theme='synthwave'] .kp-combobox__list,
    [data-theme='synthwave'] .kp-palette,
    [data-theme='synthwave'] .kp-theme-menu {
        background: var(--popover);
        border: 1px solid var(--kp-hairline);
        border-top: 4px solid transparent;
        border-image: var(--kp-stripe) 1;
        border-radius: 0;
        box-shadow: 0 12px 40px hsl(from var(--sidebar-background) h s l / 0.6);
    }

    /* Severity toasts [scope-60]. The plain toast above is repainted here in
       a later layer than kp.components, which swallowed every variant's
       plate; each is restated on the alert's token pair, as the severity
       badge wears it. */
    [data-theme='synthwave'] .kp-toast--success {
        background: var(--success);
        color: var(--success-foreground);
        border-color: var(--success);
    }

    [data-theme='synthwave'] .kp-toast--info {
        background: var(--info);
        color: var(--info-foreground);
        border-color: var(--info);
    }

    [data-theme='synthwave'] .kp-toast--warning {
        background: var(--warning);
        color: var(--warning-foreground);
        border-color: var(--warning);
    }

    [data-theme='synthwave'] .kp-toast--destructive,
    [data-theme='synthwave'] .kp-toast--error {
        background: var(--destructive);
        color: var(--destructive-foreground);
        border-color: var(--destructive);
    }

    [data-theme='synthwave']
        :is(.kp-toast--success, .kp-toast--info, .kp-toast--warning, .kp-toast--destructive, .kp-toast--error)
        :is(.kp-button--ghost, .kp-icon-button) {
        color: inherit;
    }

    /* A button hovered on a toast takes a shade of the toast's own plate
       (--kp-toast-button-hover, set in kp.components), not this theme's page hover (Kenny's second nostromo pass,
       2026-09-13). Restated here because this layer repaints the hover. */
    [data-theme='synthwave'] .kp-toast :is(.kp-button--ghost, .kp-icon-button):hover:not(:disabled) {
        background: var(--kp-toast-button-hover);
        color: inherit;
    }

    [data-theme='synthwave'] .kp-toasts {
        gap: 0.6rem;
    }

    [data-theme='synthwave'] .kp-dialog__title {
        color: var(--kp-core);
        text-shadow: var(--kp-tube-cyan);
    }

    /* The keyboard highlight is a wash of the ink, not a new colour (KT8). */
    [data-theme='synthwave'] .kp-menu__item:hover,
    [data-theme='synthwave'] .kp-combobox__option[aria-selected='true'],
    [data-theme='synthwave'] .kp-palette__option[aria-selected='true'] {
        background: hsl(from var(--foreground) h s l / 0.14);
    }

    /* The plain alert only [gap-1, Kenny 2026-09-10]. This rule used to
       repaint the ground of EVERY alert, and `kp.register` is a later layer
       than `kp.components`, so it beat `.kp-alert--destructive`'s own plate
       while that variant's ink — `--destructive-foreground`, which is drawn
       to sit ON the plate — stayed. Measured in firefox on 2026-09-12:
       seventeen of the twenty-two themes carried a destructive alert whose
       text was unreadable, grotesk at 1.00 exactly, white on white.

       Kenny saw it in chassis-rs and said to write it down and touch
       nothing; this is the round he asked for it in. Same shape as fix-12,
       one property over: a register overriding half of a pair the base
       layer defines together. */
    [data-theme='synthwave'] .kp-alert:not([class*='kp-alert--']) {
        background: var(--card);
        border: 1px solid var(--kp-hairline);
        border-left: 4px solid var(--accent);
        border-radius: 0;
    }

    [data-theme='synthwave'] .kp-alert--destructive {
        border-left-color: var(--destructive);
    }

    /* The data table's Try again takes the plate's own ink for its frame
       [Kenny's synthwave note, 2026-09-15]. The frame is the primary pink,
       and on the red plate of the failed state it measured 1.06:1 — "poorly
       visible". The alert's label is `--destructive-foreground` on that
       plate, 5.59:1, so the frame is drawn in it. Until scope-94 every
       framed button on any destructive alert took it; Kenny narrowed it to
       this one ("Alleen Try again"), so the retry control the data table
       draws in its failed slot — js/datatable.js, `[data-kp-datatable-
       retry]` inside `[data-kp-datatable-failed]`, whether the page wrote
       the slot or the script did — is the only button it reaches. */
    [data-theme='synthwave'] [data-kp-datatable-failed] .kp-button[data-kp-datatable-retry] {
        --kp-frame: var(--destructive-foreground);
    }

    [data-theme='synthwave'] .kp-alert--warning {
        border-left-color: var(--warning-foreground);
    }

    [data-theme='synthwave'] .kp-alert--success {
        border-left-color: var(--success-foreground);
    }

    [data-theme='synthwave'] .kp-alert__label {
        font-family: var(--kp-osd);
        letter-spacing: 0.12em;
        text-transform: uppercase;
    }

    [data-theme='synthwave'] .kp-grid__tile,
    [data-theme='synthwave'] .kp-split__pane {
        background: var(--card);
        border: 1px solid var(--kp-hairline);
        border-radius: 0;
    }

    [data-theme='synthwave'] .kp-grid {
        gap: 1rem;
    }

    [data-theme='synthwave'] .kp-split__separator {
        background: var(--kp-stripe);
        width: 3px;
    }

    /* Top and bottom [gap-12]: the thickness above is an inline size, so
       a horizontal split takes the same value as a block size. */
    [data-theme='synthwave'] .kp-split[data-kp-orientation='horizontal'] > .kp-split__separator {
        inline-size: auto;
        block-size: 3px;
    }

    [data-theme='synthwave'] .kp-footer {
        background: var(--sidebar-background);
        color: var(--muted-foreground);
    }

    [data-theme='synthwave'] .kp-footer h4 {
        font-family: var(--kp-osd);
        letter-spacing: 0.16em;
        text-transform: uppercase;
        color: var(--kp-pink-text);
    }

    [data-theme='synthwave'] .kp-footer a {
        font-weight: 500;
        letter-spacing: 0.06em;
        text-transform: uppercase;
        font-size: 0.85rem;
        text-decoration: none;
    }

    [data-theme='synthwave'] .kp-footer a:hover {
        color: var(--kp-core);
        text-shadow: var(--kp-tube-cyan);
    }

    /* ── Badges, tags, status: small tubes ───────────────────────────── */

    [data-theme='synthwave'] .kp-badge,
    [data-theme='synthwave'] .kp-tag {
        border-radius: var(--radius);
        border: 1px solid currentColor;
        font-family: var(--kp-osd);
        letter-spacing: 0.1em;
        text-transform: uppercase;
        box-shadow: 0 0 6px hsl(from var(--primary) h s l / 0.25);
    }

    /* The badge's type size is the package's [scope-87]; the tag keeps this register's. */
    [data-theme='synthwave'] .kp-tag {
        font-size: 0.95rem;
    }

    [data-theme='synthwave'] .kp-health__dot {
        box-shadow: 0 0 8px currentColor;
    }

    [data-theme='synthwave'] .kp-health {
        font-family: var(--kp-osd);
        letter-spacing: 0.08em;
    }

    [data-theme='synthwave'] .kp-skeleton {
        background: linear-gradient(90deg, var(--card), var(--popover), var(--card));
        border-radius: 0;
    }

    [data-theme='synthwave'] .kp-progress {
        background: var(--sidebar-background);
        border: 1px solid var(--kp-hairline);
        border-radius: 0;
    }

    [data-theme='synthwave'] .kp-spinner {
        border-color: hsl(from var(--accent) h s l / 0.25);
        border-top-color: var(--accent);
        filter: drop-shadow(0 0 4px var(--accent));
    }

    [data-theme='synthwave'] .kp-empty {
        border: 1px dashed var(--kp-hairline);
        border-radius: 0;
