    }

    [data-theme='phantom'] .kp-nav__link {
        display: block;
        position: relative;
        z-index: 0;
        padding-inline: 0.95rem;
        font-family: var(--theme-font-display);
        font-weight: 700;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        color: var(--foreground);
        text-decoration: none;
        border-radius: 0;
        background: none;
    }

    /* The measured rule: left -4%, top 18%, height 70%, width 0 → 108%,
       skewX(-16deg). */
    [data-theme='phantom'] .kp-nav__link::before {
        content: '';
        position: absolute;
        left: -4%;
        top: 14%;
        height: 72%;
        width: 0;
        background: var(--primary);
        transform: skewX(-16deg);
        z-index: -1;
    }

    [data-theme='phantom'] .kp-nav__link:hover,
    [data-theme='phantom'] .kp-nav__link:focus-visible,
    [data-theme='phantom'] .kp-nav__link[aria-current],
    [data-theme='phantom'] .kp-nav__links > li:focus-within > .kp-nav__link {
        color: var(--primary-foreground);
        background: none;
        box-shadow: none;
    }

    [data-theme='phantom'] .kp-nav__link:hover::before,
    [data-theme='phantom'] .kp-nav__link:focus-visible::before,
    [data-theme='phantom'] .kp-nav__link[aria-current]::before,
    [data-theme='phantom'] .kp-nav__links > li:focus-within > .kp-nav__link::before {
        width: 108%;
    }

    [data-theme='phantom'] .kp-nav__link[aria-haspopup]::after {
        content: ' ▾';
        font-size: 0.8em;
    }

    [data-theme='phantom'] .kp-nav__link--lang {
        border-left: 2px solid var(--border);
        margin-left: 0.5rem;
        padding-left: 0.95rem;
    }

    /* The call to action is a key cap: skewed, red, the deep red as its
       hard shadow; a press drops it onto the shadow. */
    [data-theme='phantom'] .kp-nav__link--cta {
        margin-left: 0.5rem;
        background: var(--primary);
        color: var(--primary-foreground);
        transform: skewX(var(--kp-skew));
        box-shadow: 5px 5px 0 var(--kp-red-deep);
        align-self: center;
    }

    [data-theme='phantom'] .kp-nav__link--cta::before {
        display: none;
    }

    [data-theme='phantom'] .kp-nav__link--cta:hover,
    [data-theme='phantom'] .kp-nav__link--cta:focus-visible {
        background: var(--primary);
        box-shadow: 2px 2px 0 var(--kp-red-deep);
        transform: skewX(var(--kp-skew)) translate(3px, 3px);
    }

    /* The dropdown: a cut-paper popover with the red edge, arriving on a
       three-step film cut (steps(3), one monotonic change). */
    [data-theme='phantom'] .kp-nav__menu {
        background: var(--popover);
        border: 0;
        border-left: 4px solid var(--primary);
        border-radius: 0;
        clip-path: var(--kp-paperclip);
        padding: 0.4rem 0;
        min-width: 12.5rem;
        box-shadow: none;
    }

    /* Collapsed, the dropdown is a list in the flow, not a panel [gap-12]:
       the rule above dresses the floating panel in kp.register, which
       beats the reset in kp.components, so the reset is restated here. */
    @container kp-nav (max-width: 40rem) {
        [data-theme='phantom'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open] .kp-nav__menu {
            min-width: 0;
            padding-inline-start: var(--kp-nav-menu-indent, 1rem);
            border: 0;
            background: transparent;
            box-shadow: none;
            clip-path: none;
        }
    }

    [data-theme='phantom'] .kp-nav__menu a {
        display: block;
        position: relative;
        z-index: 0;
        padding-inline: 1rem;
        font-family: var(--theme-font-display);
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
        color: var(--popover-foreground);
        text-decoration: none;
    }

    [data-theme='phantom'] .kp-nav__menu a::before {
        content: '';
        position: absolute;
        left: -2%;
        top: 10%;
        height: 80%;
        width: 0;
        background: var(--primary);
        transform: skewX(-16deg);
        z-index: -1;
    }

    [data-theme='phantom'] .kp-nav__menu a:hover,
    [data-theme='phantom'] .kp-nav__menu a:focus-visible {
        color: var(--primary-foreground);
        background: none;
    }

    [data-theme='phantom'] .kp-nav__menu a:hover::before,
    [data-theme='phantom'] .kp-nav__menu a:focus-visible::before {
        width: 104%;
    }

    /* ── Buttons: key caps — a skewed plate behind a straight label ─────── */

    /* The plate is a pseudo-element so the label stays upright: the frame
       and the fill live on ::before, the red bar that fills an outline
       button on hover on ::after. */
    [data-theme='phantom'] .kp-button {
        --kp-plate-fill: transparent;
        --kp-plate-ink: var(--foreground);
        --kp-plate-frame: var(--foreground);
        position: relative;
        isolation: isolate;
        padding-inline: 1.6rem;
        font-family: var(--theme-font-display);
        font-weight: 700;
        font-size: 1.05rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--kp-plate-ink);
        background: transparent;
        border: 0;
        border-radius: 0;
        box-shadow: none;
    }

    /* The demo skews the button itself — border, plate and the box a
       click lands in — and sets the label upright again [S49, A7, Kenny
       2026-09-08, on the comparison page that measured both hit areas].
       The plate no longer skews on its own: it inherits the element's. */
    [data-theme='phantom'] .kp-button {
        transform: skewX(var(--kp-skew));
    }

    [data-theme='phantom'] .kp-button__label {
        transform: skewX(calc(-1 * var(--kp-skew)));
    }

    [data-theme='phantom'] .kp-button::before {
        content: '';
        position: absolute;
        inset: 0;
        background: var(--kp-plate-fill);
        border: 2px solid var(--kp-plate-frame);
        z-index: -2;
    }

    [data-theme='phantom'] .kp-button::after {
        content: '';
        position: absolute;
        left: 2px;
        top: 2px;
        bottom: 2px;
        width: 0;
        background: var(--primary);
        transform: skewX(var(--kp-skew));
        transform-origin: left center;
        z-index: -1;
    }

    [data-theme='phantom'] .kp-button:hover,
    [data-theme='phantom'] .kp-button:focus-visible {
        color: var(--primary-foreground);
        background: transparent;
        box-shadow: none;
    }

    [data-theme='phantom'] .kp-button:hover::after,
    [data-theme='phantom'] .kp-button:focus-visible::after {
        width: calc(100% - 4px);
    }

    [data-theme='phantom'] .kp-button:active {
        transform: translate(3px, 3px);
    }

    /* The demo's call-to-action row: wide buttons, as in the reference. A
       pager's or a menu's button keeps its own width (DI11 at 320 px). */
    [data-theme='phantom'] [data-kp-surface='hero'] .kp-row > .kp-button {
        min-width: 12rem;
    }

    /* Two channels, outside the plate: paper hugging the button, the void
       around it (DI2, AR30). */
    [data-theme='phantom'] .kp-button:focus-visible {
        outline: none;
        box-shadow:
            0 0 0 2px var(--focus-ring-contrast),
            0 0 0 5px var(--focus-ring);
    }

    /* The primary plate is painted twice, like the mark's: the skewed
       pseudo-element for the eye, a narrower rectangle of the same red as
       the button's own background for whatever measures the ink against
       its ground. */
    [data-theme='phantom'] .kp-button--primary,
    [data-theme='phantom'] .kp-button--primary:hover,
    [data-theme='phantom'] .kp-button--primary:focus-visible {
        --kp-plate-fill: var(--primary);
        --kp-plate-ink: var(--primary-foreground);
        --kp-plate-frame: var(--primary);
        background: linear-gradient(var(--primary), var(--primary)) center / calc(100% - 14px) 100% no-repeat;
    }

    [data-theme='phantom'] .kp-button--primary {
        filter: drop-shadow(5px 5px 0 var(--kp-red-deep));
    }

    [data-theme='phantom'] .kp-button--primary::after {
        background: var(--foreground);
    }

    [data-theme='phantom'] .kp-button--primary:hover,
    [data-theme='phantom'] .kp-button--primary:focus-visible {
        filter: drop-shadow(2px 2px 0 var(--kp-red-deep));
        transform: translate(3px, 3px);
    }

    [data-theme='phantom'] .kp-button--destructive {
        --kp-plate-fill: transparent;
        --kp-plate-ink: var(--primary);
        --kp-plate-frame: var(--primary);
    }

    [data-theme='phantom'] .kp-button--ghost {
        --kp-plate-frame: transparent;
    }

    [data-theme='phantom'] .kp-button--ghost:hover,
    [data-theme='phantom'] .kp-button--ghost:focus-visible {
        --kp-plate-frame: var(--foreground);
    }

    [data-theme='phantom'] .kp-button:disabled {
        opacity: 0.45;
        transform: none;
        filter: none;
    }

    [data-theme='phantom'] .kp-button--sm {
        min-width: 0;
        padding-inline: 1rem;
        font-size: 0.9rem;
    }

    [data-theme='phantom'] .kp-icon-button {
        border: 2px solid var(--border);
        border-radius: 0;
        transform: skewX(var(--kp-skew));
    }

    [data-theme='phantom'] .kp-icon-button:hover {
        border-color: var(--foreground);
        background: var(--primary);
        color: var(--primary-foreground);
    }

    /* ── Fields ───────────────────────────────────────────────────────── */

    [data-theme='phantom'] .kp-field__label {
        font-family: var(--theme-font-display);
        font-weight: 700;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--foreground);
