    /* Both channels on the field too [S49, A5]: the register switched the
       outline off here, which left DI2 with one ring on one control. */
    [data-theme='phantom'] .kp-field__input:focus-visible {
        border-color: var(--primary);
        box-shadow: 0 0 0 2px var(--focus-ring-contrast);
    }

    [data-theme='phantom'] select.kp-field__input::picker-icon {
