    /* ── Motion, guarded [DI7] ────────────────────────────────────────── */

    /* Every animation and transition of this register lives here, inside
       the no-preference guard, so a reader who asked for reduced motion
       never receives one: the rest states above are what they get. The
       durations are literal because check-motion.mjs computes DI5's rate
       from them; the matching --kp-* knobs are what js/effects.js reads. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='phantom'] [data-kp-reveal='headline'].is-words [data-word] {
            animation: kp-shout 620ms cubic-bezier(0.22, 1, 0.36, 1) both;
            animation-delay: calc(var(--kp-i, 0) * var(--kp-word-stagger));
        }

        [data-theme='phantom'] [data-kp-reveal='rule']::after {
            transition: background-position var(--kp-rail) linear;
        }

        [data-theme='phantom'] mark::before {
            transition: transform var(--kp-plate) var(--kp-cut);
        }

        /* The rectangle under the plate switches on after the slide, in no
           time at all: a size, not a colour, so KT8's mid-transition colour
           can never be read. */
        [data-theme='phantom'] mark {
            transition: background-size 0s linear var(--kp-plate);
        }

        [data-theme='phantom'] .kp-card[data-kp-reveal='emphasis'] mark::after {
            transition: transform var(--kp-wipe) var(--kp-cut);
        }

        [data-theme='phantom'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(2)::after {
            transition-delay: var(--kp-redact-stagger);
        }

        [data-theme='phantom'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(3)::after {
            transition-delay: calc(2 * var(--kp-redact-stagger));
        }

        [data-theme='phantom'] [data-kp-surface='hero']::after {
            transition: transform 900ms var(--kp-shove);
        }

        /* Width and transform only — no colour transition: a theme applied
           after first paint transitions every colour, and CI's chromium read
           a nav link halfway (KT8; flake named, rule 8a). */
        [data-theme='phantom'] .kp-nav__link::before,
        [data-theme='phantom'] .kp-nav__menu a::before,
        [data-theme='phantom'] .kp-footer a::before,
        [data-theme='phantom'] .kp-tab::before,
        [data-theme='phantom'] .kp-button::after {
            transition: width var(--fx-duration) var(--kp-cut);
        }

        [data-theme='phantom'] .kp-nav__link--cta,
        [data-theme='phantom'] .kp-button {
            transition: transform var(--fx-duration) var(--kp-cut);
        }

        /* The film cut: three steps, one monotonic change of opacity and
           saturation together. */
        [data-theme='phantom'] .kp-nav__menu {
            transition:
                opacity 180ms steps(3, end),
                translate 180ms steps(3, end),
                filter 180ms steps(3, end);
        }

        [data-theme='phantom'] .kp-toast {
            animation: kp-cut-in 180ms steps(3, end) 1;
        }

        [data-theme='phantom'] .kp-boot::before {
            animation: kp-bar-run 900ms var(--kp-out) both;
        }

        [data-theme='phantom'] .kp-boot.is-off {
            animation: kp-load-out 640ms var(--kp-shove) 1 forwards;
        }
    }

    /* ── Motion [DI5, DI7] ────────────────────────────────────────────── */

    /* Every keyframe here has its row in TIMINGS (js/effects.js). */
    @keyframes kp-shout {
        0% {
            opacity: 0;
            transform: translateY(0.28em) skewX(-14deg);
        }

        100% {
            opacity: 1;
            transform: none;
        }
    }

    @keyframes kp-cut-in {
        0% {
            opacity: 0;
            filter: saturate(0) contrast(1.7);
        }

        60% {
            opacity: 0.6;
            filter: saturate(0.6) contrast(1.25);
        }

        100% {
            opacity: 1;
            filter: none;
        }
    }

    @keyframes kp-bar-run {
        from {
            transform: translateY(-50%) scaleX(0);
        }

        to {
            transform: translateY(-50%) scaleX(1);
        }
    }

    @keyframes kp-load-out {
        0% {
            transform: none;
        }

        50% {
            transform: skew(-20deg);
        }

        100% {
            transform: skew(-20deg) translateX(-115vw);
        }
    }

    /* The card's file code, in the red the plates wear [S49, A3]. */
    [data-theme='phantom'] .kp-nav__brand-tag {
        color: var(--primary);
        font-style: normal;
        letter-spacing: 0.2em;
