    }

    [data-theme='brutalism'] .kp-timestamp,
    [data-theme='brutalism'] .kp-id {
        color: var(--muted-foreground);
    }

    [data-theme='brutalism'] .kp-copyable__button {
        border: 2px solid var(--border-strong);
        border-radius: 0;
        box-shadow: 2px 2px 0 0 var(--border-strong);
    }

    /* The copy button's two states win over this register's own button
       rules [gap-12]: those paint in kp.register, which beats the states
       in kp.components, so copied lost its success plate and a refused
       copy looked idle. Restated token for token. */
    [data-theme='brutalism'] .kp-copyable .kp-copyable__button[data-kp-copied] {
        border-color: var(--success);
        color: var(--success-foreground);
        background: var(--success);
    }

    [data-theme='brutalism'] .kp-copyable .kp-copyable__button[data-kp-copy-failed] {
        border-color: var(--destructive);
        border-style: dashed;
        color: var(--destructive);
    }

    /* ── Data ─────────────────────────────────────────────────────────── */

    [data-theme='brutalism'] .kp-table {
        border-collapse: separate;
        border-spacing: 0;
        border: var(--kp-line) solid var(--border-strong);
        background: var(--card);
    }

    [data-theme='brutalism'] .kp-table th {
        background: var(--secondary);
        /* The reach above a sticky header paints this ground too [fix-32]. */
        --kp-datatable-head-ground: var(--secondary);
        color: var(--secondary-foreground);
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
        border-bottom: var(--kp-line) solid var(--border-strong);
    }

    [data-theme='brutalism'] .kp-table td {
        border-bottom: 1px solid var(--border-strong);
    }

    [data-theme='brutalism'] .kp-table tbody tr:hover {
