    [data-theme='brutalism'] .kp-diff__line {
        font-family: var(--theme-font-mono);
    }

    [data-theme='brutalism'] .kp-timeline {
        border-inline-start: var(--kp-line) solid var(--border-strong);
    }

    [data-theme='brutalism'] .kp-timeline__marker {
        background: var(--secondary);
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
    }

    [data-theme='brutalism'] .kp-timeline__when {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.06em;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    [data-theme='brutalism'] .kp-tree {
        font-weight: 500;
    }

    /* The accordion [gap-12]: heavy capitals like its tabs, and open is struck under with its own line weight. */
    [data-theme='brutalism'] .kp-accordion__summary {
        font-size: 0.9rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
    }

    [data-theme='brutalism'] .kp-accordion__summary::marker {
        color: var(--foreground);
    }

    [data-theme='brutalism'] .kp-accordion__item[open] > .kp-accordion__summary {
        text-decoration: underline;
        text-decoration-thickness: var(--kp-line);
    }

    [data-theme='brutalism'] .kp-reorder {
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-shadow);
    }

    /* ── Navigation and steps ─────────────────────────────────────────── */

    [data-theme='brutalism'] .kp-tab {
        border: var(--kp-line) solid transparent;
        border-radius: 0;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
    }

    [data-theme='brutalism'] .kp-tab[aria-selected='true'] {
        background: var(--secondary);
