    }

    [data-theme='brutalism'] .kp-pagination a[aria-current],
    [data-theme='brutalism'] .kp-pagination [aria-current] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: 0;
        box-shadow: 3px 3px 0 0 var(--border-strong);
    }

    [data-theme='brutalism'] .kp-wizard {
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        background: var(--card);
        box-shadow: var(--kp-shadow);
    }

    [data-theme='brutalism'] .kp-wizard__steps {
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
    }

    /* ── Pickers and palettes ─────────────────────────────────────────── */

    [data-theme='brutalism'] .kp-datepicker__day[aria-selected='true'] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: 0;
    }

    [data-theme='brutalism'] .kp-datepicker__weekday,
    [data-theme='brutalism'] .kp-datepicker__title {
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
    }

    [data-theme='brutalism'] .kp-colorpicker__swatch {
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        box-shadow: 3px 3px 0 0 var(--border-strong);
    }

    [data-theme='brutalism'] .kp-colorpicker__value {
        font-family: var(--theme-font-mono);
    }

    [data-theme='brutalism'] .kp-shortcuts__row kbd {
        font-family: var(--theme-font-mono);
        border: 2px solid var(--border-strong);
        border-radius: 0;
        box-shadow: 2px 2px 0 0 var(--border-strong);
        background: var(--card);
        display: inline-block;
        padding: 0 0.4em;
    }

    [data-theme='brutalism'] .kp-shortcuts__group-label,
    [data-theme='brutalism'] .kp-palette__group-label {
        font-family: var(--theme-font-display);
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }

    [data-theme='brutalism'] .kp-theme-menu__status,
    [data-theme='brutalism'] .kp-palette__status,
    [data-theme='brutalism'] .kp-combobox__status {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }

    /* ── The roots the rules above reach only by their parts ──────────── */

    [data-theme='brutalism'] .kp-field {
        gap: calc(var(--kp-space-xs) * 1.2);
    }

    [data-theme='brutalism'] .kp-form {
        gap: var(--kp-space-lg);
    }

    [data-theme='brutalism'] .kp-combobox,
    [data-theme='brutalism'] .kp-datepicker,
    [data-theme='brutalism'] .kp-colorpicker,
    [data-theme='brutalism'] .kp-shortcuts,
    [data-theme='brutalism'] .kp-tabs {
        border-radius: 0;
    }

    /* ── The scrollbar joins the theme ────────────────────────────────── */

    [data-theme='brutalism'] {
        scrollbar-color: var(--border-strong) var(--background);
    }

    /* ── The demo's own pieces [S46] ──────────────────────────────────── */

    [data-theme='brutalism'] .kp-side-note {
        position: absolute;
        inset-inline-end: 0.4rem;
        inset-block-start: 4.5rem;
        writing-mode: vertical-rl;
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.26em;
        text-transform: uppercase;
        color: var(--muted-foreground);
        border-inline-start: var(--kp-line) solid var(--border-strong);
        padding-inline-start: 0.5rem;
    }

    /* The laurels: three plates, each with its own ink (DI4). */
    [data-theme='brutalism'] .kp-laurels {
        gap: 0.9rem;
        font-size: 0.78rem;
        letter-spacing: 0.08em;
        text-transform: uppercase;
    }

    [data-theme='brutalism'] .kp-laurels li {
        --kp-plate: var(--secondary);
        --kp-plate-ink: var(--secondary-foreground);
        background: var(--kp-plate);
        color: var(--kp-plate-ink);
        border: var(--kp-line) solid var(--border-strong);
        box-shadow: var(--kp-shadow);
        padding: 0.55rem 0.85rem;
        max-width: 100%;
    }

    [data-theme='brutalism'] .kp-laurels li:nth-child(2) {
        --kp-plate: var(--accent);
        --kp-plate-ink: var(--accent-foreground);
    }

    [data-theme='brutalism'] .kp-laurels li:nth-child(3) {
        --kp-plate: var(--success);
        --kp-plate-ink: var(--success-foreground);
    }

    [data-theme='brutalism'] .kp-laurels b {
        display: block;
        font-family: var(--theme-font-display);
        font-weight: 400;
        font-size: 0.95rem;
        letter-spacing: -0.01em;
        text-transform: none;
    }

    [data-theme='brutalism'] .kp-lede {
        max-width: 36rem;
        font-size: 1.1rem;
    }

    /* The platforms: bordered chips on the muted plate. */
    [data-theme='brutalism'] .kp-platforms {
        margin-block-start: 2rem;
        gap: 0.5rem;
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        color: var(--foreground);
    }

    [data-theme='brutalism'] .kp-platforms span {
        border: var(--kp-line) solid var(--border-strong);
        padding: 0.25rem 0.6rem;
        background: var(--muted);
    }

    /* The spec sheet: the white card, the line, the shadow. */
    [data-theme='brutalism'] .kp-spec {
        background: var(--card);
        color: var(--card-foreground);
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-shadow);
        padding: 1.2rem 1.3rem 1.4rem;
        font-family: var(--theme-font-mono);
        font-size: 0.78rem;
        line-height: 1.7;
    }

    [data-theme='brutalism'] .kp-spec dt {
        font-weight: 700;
        text-transform: uppercase;
        letter-spacing: 0.08em;
    }

    [data-theme='brutalism'] .kp-spec__swatch {
        border: 2px solid var(--border-strong);
        border-radius: 0;
    }

    [data-theme='brutalism'] .kp-spec__font {
        font-family: var(--theme-font-display);
    }

    /* ── Motion, guarded [DI7] ────────────────────────────────────────── */

    /* Every animation and transition of this register lives here, inside
       the no-preference guard, so a reader who asked for reduced motion
       never receives one: the rest states above are what they get, and the
       marquee stands still. The durations are literal because
       check-motion.mjs computes DI5's rate from them; the matching --kp-*
       knobs are what js/effects.js reads. Position and size only — no
       colour transition anywhere (KT8). */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='brutalism'] [data-kp-reveal='headline'].is-words [data-word] {
            animation: kp-slam 260ms var(--fx-ease) both;
            animation-delay: calc(var(--kp-i, 0) * var(--kp-word-stagger));
        }

        [data-theme='brutalism'] mark {
            transition: background-size 380ms var(--fx-ease);
        }

        [data-theme='brutalism'] [data-kp-reveal='rule'].is-in::after {
            animation: kp-rule-in 620ms var(--fx-ease) 1 both;
        }

        [data-theme='brutalism'] [data-kp-divider]::before {
            animation: kp-marquee 42000ms linear infinite;
        }

        [data-theme='brutalism'] [data-kp-divider='alt']::before {
            animation-direction: reverse;
        }

        [data-theme='brutalism'] .kp-card[data-kp-reveal='emphasis'] mark::after {
            transition: transform 380ms var(--fx-ease);
        }

        [data-theme='brutalism'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(2)::after {
            transition-delay: var(--kp-redact-stagger);
        }

        [data-theme='brutalism'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(3)::after {
            transition-delay: calc(2 * var(--kp-redact-stagger));
        }

        /* What the demo moves on a hover [S49, A6 of 2026-09-08]: the
           lift, the shadow it lifts away from, and the plate colour. KT8
           held a hover to one step with no colour transition; Kenny chose
           the demo for this theme, and AR30's reader waits out
           --fx-duration after a theme switch rather than reading a ring
           mid-flight. */
        [data-theme='brutalism'] .kp-button,
        [data-theme='brutalism'] .kp-nav__link--cta {
            transition:
                translate var(--fx-duration) var(--fx-ease),
                box-shadow var(--fx-duration) var(--fx-ease),
                background-color var(--fx-duration) var(--fx-ease);
        }
    }

    /* ── Motion [DI5, DI7] ────────────────────────────────────────────── */

    /* Every keyframe here has its row in TIMINGS (js/effects.js); kp-rule-in
       is the base layer's. The slam moves a word onto its offset once; the
       marquee translates a strip -50%, seamlessly, and never changes
       luminance. */
    @keyframes kp-slam {
        from {
            transform: translate(-9px, -9px);
            text-shadow: 0 0 0 var(--secondary);
        }

        to {
            transform: none;
            text-shadow: 4px 4px 0 var(--secondary);
        }
    }

    @keyframes kp-marquee {
        from {
            transform: translateX(0);
        }

        to {
            transform: translateX(-50%);
        }
    }

    /* Stamped beside the wordmark, in the ink [S49, A3]. */
    [data-theme='brutalism'] .kp-nav__brand-tag {
        color: var(--foreground);
        font-weight: 700;
        letter-spacing: 0.14em;
    }
    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — ink on paper inverted, the fastest pass but its own hatch band. */
    [data-theme='brutalism'] .kp-marquee {
        background: var(--foreground);
        color: var(--background);
        border-block: 3px solid var(--foreground);
        font-weight: 700;
        text-transform: uppercase;
        --kp-marquee: 20000ms;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    /* A mega menu's group headings speak in the caption's voice [scope-48]. */
    [data-theme='brutalism'] .kp-nav__menu[data-kp-menu-label]::before,
    [data-theme='brutalism'] .kp-nav__menu--wide .kp-nav__menu-heading {
        background: var(--foreground);
        color: var(--background);
        font-weight: 700;
        letter-spacing: 0.02em;
        border-block-end: 0;
    }

    /* ── The side navigation [feat-nav-3] ────────────────────────────
       Not a panel but a column of slabs, each with its own hard shadow.
       The current one does not tint: it slides into its shadow and the
       shadow goes out from under it [approved by Kenny, 2026-09-11]. */
    [data-theme='brutalism'] .kp-sidenav {
        --kp-sidenav-surface: transparent;
        --kp-sidenav-gap: 0.4rem;
        border: none;
    }

    [data-theme='brutalism'] .kp-sidenav__header {
        background: var(--foreground);
        color: var(--background);
        border: 2px solid var(--foreground);
    }

    [data-theme='brutalism'] .kp-sidenav__title {
        letter-spacing: 0.18em;
        text-transform: uppercase;
        color: inherit;
    }

    [data-theme='brutalism'] .kp-sidenav__link,
    [data-theme='brutalism'] .kp-sidenav__category-toggle {
        border: 2px solid var(--foreground);
        background: var(--background);
        padding-inline: 0.75rem;
        font-weight: 700;
        text-transform: uppercase;
        border-radius: 0;
        box-shadow: 3px 3px 0 var(--foreground);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='brutalism'] .kp-sidenav__link,
        [data-theme='brutalism'] .kp-sidenav__category-toggle {
            transition:
                translate var(--fx-duration, 120ms) var(--fx-ease, ease),
                box-shadow var(--fx-duration, 120ms) var(--fx-ease, ease);
        }
    }

    [data-theme='brutalism'] .kp-sidenav__link:hover {
        translate: -1px -1px;
        box-shadow: 5px 5px 0 var(--foreground);
    }

    [data-theme='brutalism'] .kp-sidenav__link[aria-current='page'] {
        background: var(--secondary);
        color: var(--secondary-foreground);
        translate: 3px 3px;
        box-shadow: 0 0 0 var(--foreground);
    }

    /* ── Back to top, and a picture [feat-page-1, feat-media-1] ──────
       Slabs. The control sits on its shadow and moves into it when
       pressed; the frame has the same border and never rounds. */
    [data-theme='brutalism'] .kp-to-top {
        border: 2px solid var(--foreground);
        border-radius: 0;
        box-shadow: 4px 4px 0 var(--foreground);
    }

    [data-theme='brutalism'] .kp-to-top:active {
        translate: 4px 4px;
        box-shadow: 0 0 0 var(--foreground);
    }

    [data-theme='brutalism'] .kp-media {
        border: 3px solid var(--foreground);
        border-radius: 0;
        box-shadow: 6px 6px 0 var(--foreground);
    }

    [data-theme='brutalism'] .kp-media-figure > figcaption {
        text-transform: uppercase;
        font-weight: 700;
        letter-spacing: 0.06em;
        font-size: 0.75rem;
    }

    /* The figure carries the caption's voice, so the decision sits with
       the picture rather than with the words under it. */
    [data-theme='brutalism'] .kp-media-figure {
        color: var(--foreground);
        text-align: start;
    }

    /* ── The thing names itself [scope-12, approved 2026-09-11] ────────
       Brutalism labels its own construction: services on the outside,
       functions painted on the wall. So a control says what it IS when
       you touch it, in a small block-letter tag beside it.

       Kenny's two conditions, 2026-09-11: it reaches many elements rather
       than only buttons, and the words are English by default and
       replaceable. `--kp-label` is that door — a page or a single element
       sets it and the tag says whatever it was given. The defaults below
       are the fallbacks in that same declaration, which is why there is
       no string here a consumer cannot reach. */
    [data-theme='brutalism'] .kp-button,
    [data-theme='brutalism'] .kp-field__input,
    [data-theme='brutalism'] .kp-card,
    [data-theme='brutalism'] .kp-alert,
    [data-theme='brutalism'] .kp-badge {
        position: relative;
    }

    /* The side navigation says where it sits, and this tag may not argue
       with it [fix-42]. A register wins over the base layer whatever its
       specificity, so `position: relative` here took the `position: fixed`
       an `over` or `push` panel gets from css/components.css away with it
       and put the closed panel back in the flow, standing on the page
       before it was opened — Kenny, 2026-09-16, brutalism's over-the-page
       menu: "Hier staat het menu al meer dan volledig op de pagina voor ik
       het open. Het moet normaal toch 'uit het zicht' zijn?" Measured on
       catalogue/navigation.html#sidenav-over in firefox: the closed panel's
       right edge stood 621px onto the page where every other theme has it
       at 0. Those two modes are positioned already, and a positioned box is
       all the tag needs; only the `side` panel, a flex item of the page's
       own layout, has to be given one. */
    [data-theme='brutalism'] .kp-sidenav:not([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push']) {
        position: relative;
    }

    [data-theme='brutalism'] .kp-button::after,
    [data-theme='brutalism'] .kp-field__input::after,
    [data-theme='brutalism'] .kp-card::after,
    [data-theme='brutalism'] .kp-alert::after,
    [data-theme='brutalism'] .kp-badge::after,
    [data-theme='brutalism'] .kp-sidenav::after {
        position: absolute;
        inset-block-end: calc(100% + 0.3rem);
        inset-inline-start: 0;
        font-size: 0.5rem;
        letter-spacing: 0.2em;
        white-space: nowrap;
        background: var(--foreground);
        color: var(--background);
        padding: 0.1rem 0.3rem;
        opacity: 0;
        pointer-events: none;
    }

    [data-theme='brutalism'] .kp-button::after {
        content: var(--kp-label, 'BUTTON');
    }

    [data-theme='brutalism'] .kp-field__input::after {
        content: var(--kp-label, 'FIELD');
    }

    [data-theme='brutalism'] .kp-card::after {
        content: var(--kp-label, 'CARD');
    }

    [data-theme='brutalism'] .kp-alert::after {
        content: var(--kp-label, 'ALERT');
    }

    [data-theme='brutalism'] .kp-badge::after {
        content: var(--kp-label, 'BADGE');
    }

    [data-theme='brutalism'] .kp-sidenav::after {
        content: var(--kp-label, 'NAV');
    }

    [data-theme='brutalism'] .kp-button:hover::after,
    [data-theme='brutalism'] .kp-button:focus-visible::after,
    [data-theme='brutalism'] .kp-field__input:hover::after,
    [data-theme='brutalism'] .kp-field__input:focus::after,
    [data-theme='brutalism'] .kp-card:hover::after,
    [data-theme='brutalism'] .kp-alert:hover::after,
    [data-theme='brutalism'] .kp-badge:hover::after,
    [data-theme='brutalism'] .kp-sidenav:hover::after {
        opacity: 1;
    }

    /* ── The pressed state the register had been cancelling [fix-12] ───
       `kp.register` sits after `kp.components`, and a layer beats a state:
       a register writing `.kp-button:hover { background: ... }` outranks
       the base layer's `.kp-button:active`, so pressing the button changed
       nothing. Kenny found it on shade-dark, 2026-09-11 — "als ik gewoon
       blijf klikken op de knop zelf, dan gebeurt er precies niks" — and
       fifteen of the twenty-five registers had it.

       These restate the base layer's own pressed values, token for token.
       Nothing new is decided here; what the components layer already said
       is put back where the cascade can reach it. */

    [data-theme='brutalism'] .kp-button:active:not(:disabled) {
        background: var(--secondary-active);
    }

    /* ── Read-only fields [gap-11] ────────────────────────────────────── */

    /* A read-only field is a value on a record, not a box to type in. This
       register sets the field's border and ground in kp.register, which
       beats the read-only look in kp.components, so read-only painted like
       an editable field. The state is answered here, on top of the rest
       look, which stays as it was. */
    [data-theme='brutalism'] .kp-field__input[readonly] {
        border-style: dashed;
        background-color: var(--muted);
    }

    /* ── The palette's trigger in the bar [scope-48, scope-80] ─────────── */

    /* In the voice of this register's own nav links (Kenny, 2026-09-14,
       search-voice "Per thema"): heavy spaced capitals in a thick frame that
       is invisible until pointed at, when the frame and the secondary slab
       appear. The link's typeface, case, spacing, shape and pointer answer
       are restated here, because the trigger is a button beside the list
       rather than a link in it. The underline a plain link carries is not:
       it says "this is a link", and the trigger is not one. */
    [data-theme='brutalism'] .kp-nav__search .kp-nav__search-trigger {
        padding-inline: 0.75rem;
        font-weight: 700;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        border: var(--kp-line) solid transparent;
        border-radius: 0;
        background: none;
        color: var(--foreground);
    }

    [data-theme='brutalism'] .kp-nav__search .kp-nav__search-trigger:hover,
    [data-theme='brutalism'] .kp-nav__search .kp-nav__search-trigger:focus-visible {
        background: var(--secondary);
        color: var(--secondary-foreground);
        border-color: var(--border-strong);
    }

    /* ── The alarm [scope-94] ──────────────────────────────────────────────
       A stamp slammed onto the page: a red slab with a thick black border and a hard offset shadow, set at an angle, black hazard bars on the cream ground. Every colour is one of this theme's tokens. The
       button keeps this register's shape and takes the alarm's paint, on
       selectors long enough to outrank this register's own button states;
       the dialog takes no focus ring, because in the auto mode the whole
       screen is what has focus. */
    [data-theme='brutalism'] .kp-alarm {
        --kp-alarm-ground: hsl(from var(--background) h s l / 0.94);
        --kp-alarm-ink: var(--destructive-foreground);
        --kp-alarm-soft: var(--destructive-foreground);
        --kp-alarm-split: var(--foreground);
        --kp-alarm-on-ink: var(--destructive);
        --kp-alarm-glow: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-halo: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-scan: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-vignette: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-stripe: var(--foreground);
        --kp-alarm-frame: 4px solid var(--foreground);
        --kp-alarm-panel-ground: var(--destructive);
        --kp-alarm-panel-border: 4px solid var(--foreground);
        --kp-alarm-panel-shadow: 10px 10px 0 var(--foreground);
        --kp-alarm-panel-padding: clamp(0.9rem, 2.6cqi, 2.25rem);
        --kp-alarm-title-tracking: -0.02em;
        /* One step smaller, everywhere [Kenny, 2026-09-16]. His rejection of
           the auto alarm: "De tekst wordt afgebroken omdat het te groot is om
           in het kader te passen. Het hele element en subelementen mogen wat
           minder groot zijn." Measured in firefox on the raised alarm with
           the catalogue's own words, "Intrusion detected": at 1280x800 the
           headline asked the slab for 983 px of content box and got 884, so
           99 px of it was cut off by the plate; at 864x450 — the CSS viewport
           of his 2.222 zoom — the panel stood 109 px taller than the alarm's
           own box, and because the alarm centres its panel the overflow goes
           BOTH ways: the code line sat 45 px above the frame and the top of
           the headline 30 px above it, out of reach of the scroll. The
           headline drops from the package's 12cqi to 8cqi with a 5.5rem
           ceiling, the bars, the padding, the line and the shadow come down
           with it, and the plate narrows from 56rem to 44rem so the words
           have somewhere to wrap. The slab, the tilt and Archivo Black in
           capitals are untouched: this is the same stamp, one step smaller. */
        --kp-alarm-title-size: clamp(1.75rem, 8cqi, 5.5rem);
        --kp-alarm-bar: 0.7rem;
    }

    [data-theme='brutalism'] .kp-alarm:focus-visible {
        outline: none;
    }

    [data-theme='brutalism'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack,
    [data-theme='brutalism'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:hover:not(:disabled),
    [data-theme='brutalism'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:active:not(:disabled) {
        border-color: var(--kp-alarm-ink);
        background: var(--kp-alarm-ink);
        color: var(--kp-alarm-on-ink);
        text-shadow: none;
    }

    [data-theme='brutalism'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:is(:hover, :focus-visible):not(:disabled):not(:active) {
        background: var(--kp-alarm-on-ink);
        color: var(--kp-alarm-ink);
    }

    [data-theme='brutalism'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep,
    [data-theme='brutalism'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep:is(:hover, :focus-visible):not(:disabled) {
        border-color: currentColor;
        background: transparent;
        color: inherit;
        text-shadow: none;
    }

    [data-theme='brutalism'] .kp-alarm__panel {
        inline-size: min(100%, 44rem);
        rotate: -2deg;
    }

    /* The sub-elements come down with the plate [Kenny, 2026-09-16]: the code
       line, the reason and the button are the package's sizes minus a step,
       so the whole stamp shrinks together rather than the headline alone. The
       button keeps a width a thumb can find. */
    [data-theme='brutalism'] .kp-alarm__code {
        font-size: clamp(0.62rem, 1.1cqi, 0.82rem);
    }

    [data-theme='brutalism'] .kp-alarm__detail {
        font-size: clamp(0.78rem, 1.5cqi, 1.05rem);
        line-height: 1.4;
    }

    [data-theme='brutalism'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack {
        min-inline-size: 11rem;
    }
}

@layer kp.register {
    /* @kp-soft/themes — css/titanium-register.css
   The titanium register, 6.0.0 [scope-17, scope-21]. Scoped to
   [data-theme='titanium'] and inert elsewhere; opt-in, imported after
   themes.css. The approved concept demo is the third world of the
   hypertech page (2026-09-11): "Titanium wordt een nieuw thema op
   zichzelf, het is heel mooi."

   Not a place but a MATERIAL: anodised titanium over carbon weave. The
   colour has a cause. Anodising does not add pigment — it grows an oxide
   film whose thickness decides which wavelength survives — so the
   blue-violet on every edge really is interference, and it really does
   shift with the angle you look from. That is why the film's start angle
   follows the pointer rather than sitting still.

   Three things separate it from the spectral instrument, which is its
   nearest neighbour in the set and shares its shape:

     · the chamfer cuts the OTHER two corners, and carries a bright line
       along the top where the tool left the surface;
     · the ground is a carbon twill, two diagonals crossing, rather than
       an instrument's square grid;
     · metal does not ease. Sixty milliseconds, linear, and the film
       catches rather than sweeps.

   Colour discipline (DI9): nothing here names a colour. Every stop is
   `var(--token)` or `hsl(from var(--token) h s l / alpha)`. */

    [data-theme='titanium'] {
        /* The configuration surface [AR43], the demo's values as defaults. */
        --kp-reveal-threshold: 0.6;
        --kp-word-stagger: 28ms;
        --kp-redact-stagger: 90ms;
        --kp-sweep-range-start: entry 10%;
        --kp-sweep-range-end: entry 85%;
        --kp-ignite-range-start: entry 30%;
        --kp-ignite-range-end: entry 80%;
        /* The reveals this theme performs [S45]: js/effects.js reads these
           and leaves a theme that declares none at rest. No arrival: the
           demo has no boot sequence, the page is simply there. */
        --kp-reveal-headline: resolve;
        --kp-reveal-emphasis: ignite;
        --kp-reveal-rule: sweep;
        /* Dead North's shout-in ease, reused for the word resolve [S49]. */
        --kp-settle: cubic-bezier(0.22, 1, 0.36, 1);

        /* No starfield. The approved demo had one — 102 points on the
           shared texture layer with ten shimmer stars above it — and
           Kenny took it back out on 2026-09-11: "dark mag zijn sterren
           weer kwijtspelen op de achtergrond". The ground is plain now.
           The divider keeps its own dense local sample, which is a seam
           between sections rather than the background he named. */

        /* -- The oxide film [scope-17] ---------------------------------
           Anodising grows a film whose thickness decides which wavelength
           survives, so the colour shifts with the angle you look from. A
           gradient cannot read a pointer; js/effects.js writes the angle
           down when a theme asks for it.

           A LINEAR sweep here where the spectral instrument uses a conic
           one: an oxide on a flat machined face runs across the surface,
           it does not turn about a point. The pointer tilts it by sixty
           degrees either way, which is the range of angles you get by
           moving your head in front of a real anodised part. */
        --kp-pointer: track;
        --kp-px: 0.5;
        --kp-py: 0.5;
        --kp-iris: linear-gradient(calc(70deg + var(--kp-px) * 60deg), var(--chart-1), var(--chart-2), var(--chart-3), var(--chart-1));
        /* The milled corner, cut on the OTHER diagonal from the spectral
           instrument's: leading-top and trailing-bottom, the way a part is
           relieved to clear a fixture. */
        --kp-chamfer: var(--fx-notch, 0.6rem);
        --kp-chamfer-panel: 1.2rem;
        /* The line the tool left along the top face. */
        --kp-tool-edge: inset 0 1px 0 hsl(from var(--foreground) h s l / 0.14);
    }

    /* ── The chamfer [scope-16] ────────────────────────────────────────
       Controls take the small cut and panels the large one. `clip-path`
       rather than a border-radius, because the corner is a straight edge
       at forty-five degrees and a radius is an arc. */
    [data-theme='titanium'] .kp-button,
    [data-theme='titanium'] .kp-field__input,
    [data-theme='titanium'] .kp-badge {
        clip-path: polygon(
            var(--kp-chamfer) 0,
            100% 0,
            100% calc(100% - var(--kp-chamfer)),
            calc(100% - var(--kp-chamfer)) 100%,
            0 100%,
            0 var(--kp-chamfer)
        );
        box-shadow: var(--kp-tool-edge);
    }

    [data-theme='titanium'] .kp-card,
    [data-theme='titanium'] .kp-dialog,
    [data-theme='titanium'] .kp-alert {
        clip-path: polygon(
            var(--kp-chamfer-panel) 0,
            100% 0,
            100% calc(100% - var(--kp-chamfer-panel)),
            calc(100% - var(--kp-chamfer-panel)) 100%,
            0 100%,
            0 var(--kp-chamfer-panel)
        );
        box-shadow: var(--kp-tool-edge);
    }

    /* ── The instrument's own button [scope-16] ────────────────────────
       Three things happen at once and none of them is a colour change:
       two brackets close on the label, the label draws itself in a little,
       and the oxide runs along the bottom edge. The brackets are the
       button's own pseudo-elements; the oxide is `.kp-button__edge`, which
       the component now provides precisely because both were needed.

       `content` here is a glyph, not a word: nothing to translate, and so
       nothing KT5 has to police. */
    /* No brackets. Those are the spectral instrument's notation — a
       machine annotating what it has selected — and a material does not
       annotate. Titanium's two pseudo-element slots stay free. */

    [data-theme='titanium'] .kp-button__edge {
        background: var(--kp-iris);
        mix-blend-mode: screen;
        opacity: 0;
        z-index: 1;
    }

    [data-theme='titanium'] .kp-button:hover .kp-button__edge,
    [data-theme='titanium'] .kp-button:focus-visible .kp-button__edge {
        opacity: 0.26;
    }

    [data-theme='titanium'] .kp-button__label {
        position: relative;
        z-index: 2;
    }

    /* No give. The spectral instrument draws its label in on hover; metal
       does not compress, so titanium answers a press by dropping the whole
       control one pixel.

       The face goes into its seat [Kenny's titanium note, 2026-09-15].
       "There is no click effect": the one pixel ran over the theme's 60ms,
       and on the bare, secondary, ghost and mirror buttons the pressed
       ground was three RGB steps from the hover ground, so a click showed
       nothing. Still no give and no glow — the face does not shrink and
       nothing blooms — but a pressed part is out of the light: the bright
       tool edge along its top goes out and a hairline of shadow takes its
       place, the ground drops a full step (below, with the fix-12 rules),
       and all of it arrives at once, because a click is shorter than a
       transition. The release runs back over the same 60ms, linear. A
       keyboard press keeps the focus ring, which owns the shadow while
       it shows. */
    [data-theme='titanium'] .kp-button:active:not(:disabled) {
        translate: 0 1px;
        transition-duration: 0s;
    }

    [data-theme='titanium'] .kp-button:active:not(:disabled):not(:focus-visible) {
        box-shadow: inset 0 1px 0 hsl(from var(--background) h s l / 0.7);
    }

    /* The reading above the control: the consumer's own word, in the
       theme's monospace, taking the oxide's colours through the text. */
    [data-theme='titanium'] .kp-button__readout {
        inset-block-end: calc(100% + 0.2rem);
        font-family: var(--theme-font-mono);
        font-size: 0.5rem;
        letter-spacing: 0.22em;
        text-transform: uppercase;
        color: var(--muted-foreground);
        translate: 0 0.2rem;
    }

    [data-theme='titanium'] .kp-button:hover .kp-button__readout,
    [data-theme='titanium'] .kp-button:focus-visible .kp-button__readout {
        opacity: 1;
        translate: 0 0;
        background: var(--kp-iris);
        background-clip: text;
        color: transparent;
    }

    /* ── Room for the readout above the chamfer [Kenny's note, 2026-09-15]
       The chamfer is a clip-path, and a clip-path clips the element's
       descendants too, so the readout — which sits above the control, out
       of its box — was cut away entirely: at full opacity on hover and not
       one pixel painted, on the catalogue and on the concept page alike.
       A button that carries a readout keeps its chamfer and adds a strip
       above it for the readout to show in. The strip is an island, joined
       to the chamfer by a zero-width seam along the end edge (the start
       corner is the cut one), and it stops the width of the focus ring and
       its outline short of the control, so none of the ring the chamfer
       cuts away reappears on top. It reaches well past both ends because
       the readout does not wrap. */
    [data-theme='titanium'] .kp-button:has(> .kp-button__readout) {
        --kp-readout-seam: calc(-1 * (var(--focus-ring-width, 2px) + var(--kp-focus-ring-inner-width, 2px) + 1px));
        clip-path: polygon(
            var(--kp-chamfer) 0,
            100% 0,
            100% var(--kp-readout-seam),
            calc(100% + 12rem) var(--kp-readout-seam),
            calc(100% + 12rem) -2rem,
            -12rem -2rem,
            -12rem var(--kp-readout-seam),
            100% var(--kp-readout-seam),
            100% 0,
            100% calc(100% - var(--kp-chamfer)),
            calc(100% - var(--kp-chamfer)) 100%,
            0 100%,
            0 var(--kp-chamfer)
        );
    }

    @media (prefers-reduced-motion: no-preference) {
        /* Metal does not ease. Sixty milliseconds -- the theme's own
           --fx-duration -- and LINEAR, because an eased curve is the
           signature of something with give in it. The film takes half as
           long again, which is the one place a little softness belongs:
           an interference colour arrives as the angle changes, not as a
           switch closes. */
        [data-theme='titanium'] .kp-button,
        [data-theme='titanium'] .kp-button__edge,
        [data-theme='titanium'] .kp-button__readout {
            transition:
                background var(--fx-duration) linear,
                border-color var(--fx-duration) linear,
                color var(--fx-duration) linear,
                translate var(--fx-duration) linear,
                opacity calc(var(--fx-duration) * 1.5) linear;
        }
    }

    /* ── The field's own oxide line [scope-16] ─────────────────────────── */
    [data-theme='titanium'] .kp-field {
        position: relative;
    }

    [data-theme='titanium'] .kp-field::after {
        content: '';
        position: absolute;
        inset-inline: 0;
        inset-block-end: -1px;
        block-size: 1px;
        background: var(--kp-iris);
        scale: 0 1;
        transform-origin: left center;
        pointer-events: none;
    }

    [data-theme='titanium'] .kp-field:focus-within::after {
        scale: 1 1;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='titanium'] .kp-field::after {
            transition: scale calc(var(--fx-duration) * 1.5) var(--fx-ease);
        }
    }

    /* ── The ring, reversed from the base default [DI2, AR30, S49] ────────
       The base layer puts the theme's foreground on the inner ring and its
       background on the outer one; the approved demo's own :focus-visible
       does it the other way — the void touching the element, the ink
       outside it — and DI2's promise holds either way, since one of the
       two always clears 3:1 on the surface behind it. */
    [data-theme='titanium'] :focus-visible {
        outline-color: var(--foreground);
        box-shadow: 0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--background);
    }

    /* ── The ring inside the chamfer [fix-38, DI2] ─────────────────────
       The chamfer's clip-path cuts away everything outside the button's
       box, the outline and the outer shadow above included: tabbing to a
       button changed 0 pixels on or outside its edge. So on a clipped
       control both channels go inside, along the edge, where the clip
       cannot reach — the answer the menu item already gives. The ink
       (--focus-ring) runs along the edge and the void
       (--focus-ring-contrast) inside it, the same order as the ring
       outside. The outline stays declared and stays clipped. */
    [data-theme='titanium'] .kp-button:focus-visible {
        box-shadow:
            inset 0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring),
            inset 0 0 0 calc(var(--kp-focus-ring-inner-width, 2px) + 2px) var(--focus-ring-contrast);
    }

    /* ── Type ──────────────────────────────────────────────────────────── */

    [data-theme='titanium'] h1,
    [data-theme='titanium'] h2,
    [data-theme='titanium'] h3 {
        font-family: var(--theme-font-display);
        font-weight: 700;
        color: var(--foreground);
    }

    [data-theme='titanium'] [data-kp-surface] h1 {
        letter-spacing: -0.02em;
        margin-block: 0 0.35em;
        text-wrap: balance;
    }

    /* The headline reveal: the module wraps each word in its own span
       (`[data-word]`, `--kp-i` its index); at rest — no script, or the
       reveal already ran — every word is already its own inline-block
       with nothing applied, which is the finished look. */
    [data-theme='titanium'] [data-kp-reveal='headline'] [data-word] {
        display: inline-block;
    }

    /* Microlabels: a quiet dot before the label, the theme's own violet. */
    [data-theme='titanium'] .microlabel {
        font-family: var(--theme-font-body);
        font-size: 0.7rem;
        letter-spacing: 0.2em;
        text-transform: uppercase;
        color: var(--muted-foreground);
        line-height: 1.3;
    }

    [data-theme='titanium'] .microlabel::before {
        content: '· ';
        color: var(--primary);
    }

    /* ── The hooks [S45]: the mark, the rule, the divider ─────────────── */

    /* The mark, its default and general reading: an ignite. At rest — no
       script, reduced motion, or a browser without scroll-driven
       animations — the words already stand in the finished signal: never
       an invisible or half-drawn state (DI7). */
    [data-theme='titanium'] mark {
        background: none;
        color: var(--primary);
        font-weight: 600;
        text-decoration: underline 2px solid var(--border-strong);
        text-underline-offset: 0.18em;
    }

    @media (prefers-reduced-motion: no-preference) {
        @supports (animation-timeline: view()) {
            [data-theme='titanium'] mark {
                color: var(--muted-foreground);
                text-decoration-color: var(--border);
                animation: kp-ignite linear both;
                animation-timeline: view();
                animation-range: var(--kp-ignite-range-start) var(--kp-ignite-range-end);
            }
        }
    }

    /* The rule: the oxide across the heading's whole width, drawn from the
       leading edge as the heading arrives [scope-16]. The demo draws it as
       a scaleX on a two-pixel band rather than the old sweep of a gradient
       position, because the band IS the film here — there is nothing to
       slide, only more or less of it. At rest it stands fully drawn. */
    [data-theme='titanium'] [data-kp-reveal='rule'] {
        position: relative;
        padding-block-end: 0.6rem;
    }

    [data-theme='titanium'] [data-kp-reveal='rule']::after {
        content: '';
        position: absolute;
        inset-inline: 0;
        inset-block-end: 0;
        block-size: 2px;
        background: var(--kp-iris);
        scale: 1 1;
        transform-origin: left center;
    }

    @media (prefers-reduced-motion: no-preference) {
        @supports (animation-timeline: view()) {
            [data-theme='titanium'] [data-kp-reveal='rule']::after {
                animation: kp-draw linear both;
                animation-timeline: view();
                animation-range: var(--kp-sweep-range-start) var(--kp-sweep-range-end);
            }
        }
    }

    /* The divider: the instrument's own scale. A hairline that fades at
       both ends, with tick marks standing on it every three rem — the
       edge of a ruler rather than a decorative seam. No starfield and no
       colour of its own: every stop is a token. */
    [data-theme='titanium'] [data-kp-divider] {
        position: relative;
        display: block;
        block-size: var(--kp-divider-height, 3.75rem);
        overflow: hidden;
    }

    /* A milled groove, not a drawn line: a dark channel with a bright lip
       above and below it, which is what a cut in metal looks like. */
    [data-theme='titanium'] [data-kp-divider]::before {
        content: '';
        position: absolute;
        inset-inline: var(--kp-divider-inset, 6%);
        inset-block-start: 50%;
        block-size: 3px;
        border-radius: 2px;
        background: hsl(from var(--background) h s calc(l * 0.7));
        box-shadow:
            inset 0 1px 0 hsl(from var(--foreground) h s l / 0.1),
            0 1px 0 hsl(from var(--foreground) h s l / 0.07);
    }

    /* And the film sitting in the groove. */
    [data-theme='titanium'] [data-kp-divider]::after {
        content: '';
        position: absolute;
        inset-inline: 22%;
        inset-block-start: 50%;
        block-size: 1px;
        background: var(--kp-iris);
        opacity: 0.75;
    }

    [data-theme='titanium'] [data-kp-divider='alt'] {
        transform: scaleX(-1);
    }

    /* ── The hero ──────────────────────────────────────────────────────── */

    [data-theme='titanium'] [data-kp-surface='hero'] {
        position: relative;
        padding-block: 3rem 4.5rem;
    }

    [data-theme='titanium'] [data-kp-surface='hero'] [data-kp-hero-grid] {
        grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
        gap: 2.5rem;
        align-items: end;
    }

    @container (max-width: 54rem) {
        [data-theme='titanium'] [data-kp-surface='hero'] [data-kp-hero-grid] {
            grid-template-columns: 1fr;
        }
    }

    /* The margin note: a difference-blend chrome over the hero's own glow —
       there is no photograph to invert over (S48), so the "imagery" is the
       glow itself. Decorative, aria-hidden, never carries text a reader
       needs (checked against every surface it might land on: over the
       void 13.36, over the panel 11.72, over the glow itself only 2.19 —
       the reason it stays hidden from assistive tech rather than relied
       on). */
    [data-theme='titanium'] .kp-side-note {
        position: absolute;
        inset-inline-end: 0.35rem;
        inset-block-start: 2rem;
        writing-mode: vertical-rl;
        font-family: var(--theme-font-mono);
        font-size: 0.65rem;
        letter-spacing: 0.3em;
        text-transform: uppercase;
        color: var(--foreground);
        mix-blend-mode: difference;
        z-index: 2;
        padding: 0.4rem 0.1rem;
    }

    @media (max-width: 40rem) {
        [data-theme='titanium'] .kp-side-note {
            display: none;
        }
    }

    /* ── The navbar: quiet, no chrome of its own beyond the ground ─────── */

    [data-theme='titanium'] .kp-nav-wrap {
        background: var(--card);
        border-bottom: 1px solid var(--border-strong);
    }

    [data-theme='titanium'] .kp-nav {
        background: var(--card);
        padding-block: calc(var(--kp-nav-pad-block, 0.7rem) * var(--kp-nav-pad-scale, 1));
    }

    [data-theme='titanium'] .kp-nav__brand {
        font-weight: 700;
        font-size: 1.25rem;
        letter-spacing: -0.01em;
        color: var(--foreground);
    }

    [data-theme='titanium'] .kp-nav__links {
        gap: 0.15rem;
    }

    [data-theme='titanium'] .kp-nav__link {
        padding-inline: 0.8rem;
        border-radius: var(--radius);
        font-weight: 500;
        color: var(--muted-foreground);
    }

    [data-theme='titanium'] .kp-nav__link:hover,
    [data-theme='titanium'] .kp-nav__link:focus-visible,
    [data-theme='titanium'] .kp-nav__link[aria-current],
    [data-theme='titanium'] .kp-nav__links > li:focus-within > .kp-nav__link {
        color: var(--foreground);
        background: var(--accent);
    }

    /* The ring above the next link's plate [fix-38]: the links sit 0.15rem
       apart and the ring reaches 4px out, so a later item — the current
       page's accent plate — painted over its end side (5% of it changed on
       focus). The focused item is lifted over its neighbours. */
    [data-theme='titanium'] .kp-nav__links > li:has(> .kp-nav__link:focus-visible) {
        z-index: 1;
    }

    [data-theme='titanium'] .kp-nav__link[aria-haspopup]::after {
        content: ' ⌄';
        font-size: 0.8em;
    }

    [data-theme='titanium'] .kp-nav__link--lang {
        border-inline-start: 1px solid var(--border);
        margin-inline-start: 0.5rem;
        padding-inline-start: 0.7rem;
    }

    [data-theme='titanium'] .kp-nav__link--cta {
        margin-inline-start: 0.25rem;
        background: var(--primary);
        color: var(--primary-foreground);
        font-weight: 600;
    }

    [data-theme='titanium'] .kp-nav__link--cta:hover,
    [data-theme='titanium'] .kp-nav__link--cta:focus-visible {
        background: var(--foreground);
        color: var(--background);
    }

    /* The dropdown: a quiet dark panel, the theme's own edge, and — the
       thing every one of the first batch's demos left unstyled (KT14) —
       its own keyboard state, the theme's own violet rather than the
       page-wide ink outline. */
    [data-theme='titanium'] .kp-nav__menu {
        background: var(--card);
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
        padding: 0.3rem;
        min-width: 12rem;
        box-shadow: 0 12px 28px hsl(from var(--background) h s l / 0.45);
    }

    /* Collapsed, the dropdown is a list in the flow, not a panel [gap-12]:
       the rule above dresses the floating panel in kp.register, which
       beats the reset in kp.components, so the reset is restated here. */
    @container kp-nav (max-width: 40rem) {
        [data-theme='titanium'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open] .kp-nav__menu {
            min-width: 0;
            padding-inline-start: var(--kp-nav-menu-indent, 1rem);
            border: 0;
            background: transparent;
            box-shadow: none;
        }
    }

    [data-theme='titanium'] .kp-nav__menu a {
        display: block;
        padding-inline: 0.7rem;
        border-radius: calc(var(--radius) / 1.5);
        color: var(--foreground);
    }

    [data-theme='titanium'] .kp-nav__menu a:hover {
        background: var(--accent);
    }

    [data-theme='titanium'] .kp-nav__menu a:focus-visible {
        background: var(--accent);
        outline: 2px solid var(--primary);
        outline-offset: -2px;
        box-shadow: none;
    }

    /* ── Buttons: a flat panel, an edge, no bevel ──────────────────────── */

    [data-theme='titanium'] .kp-button,
    [data-theme='titanium'] .kp-icon-button {
        background: var(--card);
        color: var(--foreground);
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
        font-weight: 600;
    }

    [data-theme='titanium'] .kp-button:hover {
        background: var(--accent);
    }

    [data-theme='titanium'] [data-kp-surface='hero'] .kp-row > .kp-button {
        min-width: min(11rem, 100%);
    }

    [data-theme='titanium'] .kp-button--primary,
    [data-theme='titanium'] .kp-button--primary:hover {
        background: var(--primary);
        border-color: var(--primary);
        color: var(--primary-foreground);
    }

    /* A step down, not up [scope-80]. The primary is a pale metal on a
       dark ground, and six points lighter took it to a near-white nobody
       could tell from the rest: measured on catalogue/button.html, rest to
       hover was 4.9 in OKLab distance where roughly 10 is "tells them
       apart", and the bare button's hover is 8.9. Fourteen points darker is
       11.4, and the pressed state below goes a further thirteen, so pressed
       stays 11.0 from hover (DI3's floor of 10). */
    [data-theme='titanium'] .kp-button--primary:hover {
        background: hsl(from var(--primary) h s calc(l - 14));
        border-color: hsl(from var(--primary) h s calc(l - 14));
    }

    [data-theme='titanium'] .kp-button--ghost {
        background: transparent;
        border-color: transparent;
        color: var(--foreground);
    }

    [data-theme='titanium'] .kp-button--ghost:hover {
        background: var(--accent);
        border-color: var(--border-strong);
    }

    [data-theme='titanium'] .kp-button--destructive {
        background: transparent;
        border-color: var(--destructive);
        color: var(--destructive);
    }

    [data-theme='titanium'] .kp-button--destructive:hover {
        background: var(--destructive);
        color: var(--destructive-foreground);
    }

    [data-theme='titanium'] .kp-button:disabled {
        opacity: 0.45;
    }

    /* ── Fields: a panel and an edge, the violet as focus ──────────────── */

    [data-theme='titanium'] .kp-field__label {
        font-weight: 600;
        color: var(--foreground);
    }

    [data-theme='titanium'] .kp-field__input,
    [data-theme='titanium'] .kp-datatable__search,
    [data-theme='titanium'] .kp-combobox__input,
    [data-theme='titanium'] .kp-palette__input {
        background: var(--card);
        color: var(--foreground);
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
    }

    [data-theme='titanium'] .kp-field__input:focus,
    [data-theme='titanium'] .kp-datatable__search:focus,
    [data-theme='titanium'] .kp-combobox__input:focus,
    [data-theme='titanium'] .kp-palette__input:focus {
        border-color: var(--primary);
    }

    /* One arrow on a select, never two [fix-42]. The same three lines dark
       carried, with the same fault: a chevron in two 6px gradients and
       nothing taking the browser's own arrow away, so firefox drew its
       dropmarker beside it (19 columns of ink over the select's right edge
       against the 8 of a theme that leaves the arrow to the browser, and
       still 8 with this register's own arrow forced off). Found by sweeping
       all 22 themes for what Kenny reported in dark; these two were the
       only pair, and the sweep is tests/register-dark-faults.spec.mjs. The arrow
       goes back to the browser, which also reserves the room for it, and
       the picker icon wears the theme where the page may take the list
       over [KT8]. */
    [data-theme='titanium'] select.kp-field__input::picker-icon {
        color: var(--muted-foreground);
    }

    [data-theme='titanium'] .kp-field__help {
        color: var(--muted-foreground);
    }

    [data-theme='titanium'] .kp-field--invalid .kp-field__input {
        border-color: var(--destructive);
    }

    [data-theme='titanium'] .kp-field__error {
        color: var(--destructive);
    }

    [data-theme='titanium'] .kp-field__check {
        appearance: none;
        inline-size: 1.15rem;
        block-size: 1.15rem;
        border: 1px solid var(--border-strong);
        border-radius: 0.25rem;
        background: var(--card);
        display: grid;
        place-items: center;
    }

    [data-theme='titanium'] .kp-field__check:checked {
        background: var(--primary);
        border-color: var(--primary);
    }

    [data-theme='titanium'] .kp-field__check:checked::before {
        content: '';
        width: 0.5rem;
        height: 0.5rem;
        border-radius: 0.1rem;
        background: var(--primary-foreground);
    }

    [data-theme='titanium'] .kp-fieldset {
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
    }

    /* The switch [gap-11], in the checkbox's voice: the machined corner on
       the card, a small square thumb, and the primary fill once on. */
    [data-theme='titanium'] .kp-switch {
        --kp-switch-radius: 0.25rem;
        --kp-switch-thumb-radius: 0.1rem;
    }

    [data-theme='titanium'] .kp-switch__input {
        border: 1px solid var(--border-strong);
        background: var(--card);
    }

    [data-theme='titanium'] .kp-switch__input:checked {
        background: var(--primary);
        border-color: var(--primary);
    }

    [data-theme='titanium'] .kp-form__summary {
        background: var(--card);
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
    }

    /* ── Cards, the dossier: a quiet panel, the redact bar ─────────────── */

    [data-theme='titanium'] .kp-card {
        background: var(--card);
        border: 1px solid var(--border-strong);
        border-radius: calc(var(--radius) * 1.5);
    }

    [data-theme='titanium'] .kp-card__title {
        font-weight: 700;
    }

    /* The stamp: attr(data-kp-label) content, the convention
       css/cyberpunk-register.css already uses for the same slot. */
    [data-theme='titanium'] .kp-card[data-kp-label]::before {
        content: attr(data-kp-label);
        position: absolute;
        top: 1rem;
        right: 1rem;
        background: var(--primary);
        color: var(--primary-foreground);
        font-family: var(--theme-font-mono);
        font-size: 0.68rem;
        font-weight: 600;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        padding: 0.2rem 0.55rem;
        border-radius: 999px;
    }

    [data-theme='titanium'] .kp-card[data-kp-reveal='emphasis'] {
        position: relative;
    }

    /* The dossier's own reading of the mark: not the ignite above, but a
       redact bar in the theme's edge colour that lifts off, right to
       left, on the trigger — the demo's own mechanism for this slot,
       distinct from the lede's colour-only ignite the general rule above
       answers. The bar sits on the mark's own ::after so what a reader
       hears (the text itself) is never removed, only its paint. */
    [data-theme='titanium'] .kp-card[data-kp-reveal='emphasis'] mark {
        position: relative;
        color: var(--foreground);
        background: none;
        text-decoration: none;
        font-weight: 400;
        white-space: nowrap;
        border-radius: 0.2em;
    }

    [data-theme='titanium'] .kp-card[data-kp-reveal='emphasis'] mark::after {
        content: '';
        position: absolute;
        inset: -0.05em -0.15em;
        background: var(--border-strong);
        border-radius: 0.2em;
        transform: scaleX(0);
        transform-origin: right center;
        pointer-events: none;
    }

    [data-theme='titanium'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:not(.is-cleared) {
        color: transparent;
    }

    [data-theme='titanium'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:not(.is-cleared)::after {
        transform: scaleX(1);
    }

    /* ── Panels: a quiet dark ground, the theme's own edge ─────────────── */

    [data-theme='titanium'] .kp-dialog,
    [data-theme='titanium'] .kp-popover,
    [data-theme='titanium'] .kp-menu,
    [data-theme='titanium'] .kp-toast,
    [data-theme='titanium'] .kp-tooltip,
    [data-theme='titanium'] .kp-confirm,
    [data-theme='titanium'] .kp-datepicker__panel,
    [data-theme='titanium'] .kp-combobox__list,
    [data-theme='titanium'] .kp-palette,
    [data-theme='titanium'] .kp-theme-menu {
        background: var(--card);
        color: var(--foreground);
        border: 1px solid var(--border-strong);
        border-radius: calc(var(--radius) * 1.5);
        box-shadow: 0 12px 28px hsl(from var(--background) h s l / 0.45);
    }

    /* Severity toasts [scope-60]. The plain toast above is repainted here in
       a later layer than kp.components, which swallowed every variant's
       plate; each is restated on the alert's token pair, as the severity
       badge wears it. */
    [data-theme='titanium'] .kp-toast--success {
        background: var(--success);
        color: var(--success-foreground);
        border-color: var(--success);
    }

    [data-theme='titanium'] .kp-toast--info {
        background: var(--info);
        color: var(--info-foreground);
        border-color: var(--info);
    }

    [data-theme='titanium'] .kp-toast--warning {
        background: var(--warning);
        color: var(--warning-foreground);
        border-color: var(--warning);
    }

    [data-theme='titanium'] .kp-toast--destructive,
    [data-theme='titanium'] .kp-toast--error {
        background: var(--destructive);
        color: var(--destructive-foreground);
        border-color: var(--destructive);
    }

    [data-theme='titanium']
        :is(.kp-toast--success, .kp-toast--info, .kp-toast--warning, .kp-toast--destructive, .kp-toast--error)
        :is(.kp-button--ghost, .kp-icon-button) {
        color: inherit;
    }

    /* A button hovered on a toast takes a shade of the toast's own plate
       (--kp-toast-button-hover, set in kp.components), not this theme's page hover (Kenny's second nostromo pass,
       2026-09-13). Restated here because this layer repaints the hover. */
    [data-theme='titanium'] .kp-toast :is(.kp-button--ghost, .kp-icon-button):hover:not(:disabled) {
        background: var(--kp-toast-button-hover);
        color: inherit;
    }

    [data-theme='titanium'] .kp-dialog__title {
        font-weight: 700;
    }

    /* Phase 7, `focus-ring`. The keyboard landing on an item inside the
       row menu painted nothing at all in this theme — measured `outside:
       0 focused, 0 at rest`. The popover rounds its corners and the item
       fills it, so a ring drawn outside the item has nowhere to land;
       cyberpunk hit the same wall when its bevel came back and answered
       it the same way. Both channels go INSIDE, where nothing can clip
       them: the ring colour first, the contrast colour behind it. */
    [data-theme='titanium'] .kp-menu__item:focus-visible {
        outline: none;
        background: var(--accent);
        box-shadow:
            inset 0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring),
            inset 0 0 0 calc(var(--kp-focus-ring-inner-width, 2px) + 2px) var(--focus-ring-contrast);
    }

    [data-theme='titanium'] .kp-menu__item:hover {
        background: var(--accent);
    }

    /* The plain alert only [gap-1, Kenny 2026-09-10]. This rule used to
       repaint the ground of EVERY alert, and `kp.register` is a later layer
       than `kp.components`, so it beat `.kp-alert--destructive`'s own plate
       while that variant's ink — `--destructive-foreground`, which is drawn
       to sit ON the plate — stayed. Measured in firefox on 2026-09-12:
       seventeen of the twenty-two themes carried a destructive alert whose
       text was unreadable, grotesk at 1.00 exactly, white on white.

       Kenny saw it in chassis-rs and said to write it down and touch
       nothing; this is the round he asked for it in. Same shape as fix-12,
       one property over: a register overriding half of a pair the base
       layer defines together. */
    [data-theme='titanium'] .kp-alert:not([class*='kp-alert--']) {
        background: var(--card);
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
    }

    [data-theme='titanium'] .kp-alert__label {
        font-weight: 700;
    }

    [data-theme='titanium'] .kp-grid__tile,
    [data-theme='titanium'] .kp-split__pane {
        background: var(--card);
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
    }

    [data-theme='titanium'] .kp-split__separator {
        background: var(--border);
    }

    /* ── The footer: one step darker than the ground ───────────────────── */

    [data-theme='titanium'] .kp-footer {
        background: var(--sidebar-background);
        color: var(--muted-foreground);
    }

    [data-theme='titanium'] .kp-footer h4 {
        color: var(--foreground);
    }

    [data-theme='titanium'] .kp-footer a {
        color: var(--muted-foreground);
        font-size: 0.92rem;
    }

    [data-theme='titanium'] .kp-footer a:hover,
    [data-theme='titanium'] .kp-footer a:focus-visible {
        color: var(--foreground);
    }

    /* ── Badges, tags, status ───────────────────────────────────────────── */

    [data-theme='titanium'] .kp-badge,
    [data-theme='titanium'] .kp-tag {
        border: 1px solid var(--border-strong);
    }

    [data-theme='titanium'] .kp-skeleton {
        background: var(--accent);
    }

    [data-theme='titanium'] .kp-progress {
        background: var(--card);
        border: 1px solid var(--border-strong);
    }

    [data-theme='titanium'] .kp-spinner {
        border-color: var(--border);
        border-top-color: var(--primary);
    }

    [data-theme='titanium'] .kp-empty {
        border: 1px dashed var(--border-strong);
    }

    [data-theme='titanium'] .kp-error {
        color: var(--destructive);
    }

    /* ── Text shapes ──────────────────────────────────────────────────── */

    [data-theme='titanium'] .kp-id,
    [data-theme='titanium'] .kp-url,
    [data-theme='titanium'] .kp-numeric,
    [data-theme='titanium'] .kp-timestamp,
    [data-theme='titanium'] .kp-masked,
    [data-theme='titanium'] .kp-copyable,
    [data-theme='titanium'] .kp-truncate,
    [data-theme='titanium'] .kp-cell-break,
    [data-theme='titanium'] .kp-cell-truncate {
        font-family: var(--theme-font-mono);
    }

    [data-theme='titanium'] .kp-timestamp,
    [data-theme='titanium'] .kp-id {
        color: var(--muted-foreground);
    }

    [data-theme='titanium'] .kp-copyable__button {
        border: 1px solid var(--border-strong);
    }

    /* The copy button's two states win over this register's own button
       rules [gap-12]: those paint in kp.register, which beats the states
       in kp.components, so copied lost its success plate and a refused
       copy looked idle. Restated token for token. */
    [data-theme='titanium'] .kp-copyable .kp-copyable__button[data-kp-copied] {
        border-color: var(--success);
        color: var(--success-foreground);
        background: var(--success);
    }

    [data-theme='titanium'] .kp-copyable .kp-copyable__button[data-kp-copy-failed] {
        border-color: var(--destructive);
        border-style: dashed;
        color: var(--destructive);
    }

    /* ── Data ─────────────────────────────────────────────────────────── */

    [data-theme='titanium'] .kp-table th {
        color: var(--muted-foreground);
