    }

    [data-theme='shade-light'] [data-kp-divider='alt']::before {
        --fx-texture: linear-gradient(180deg, transparent, hsl(from var(--accent) h s l / 1) 55%, transparent);
        --fx-texture-opacity: 0.06;
    }

    /* ── The hero: the opening surface ───────────────────────────────── */

