        text-decoration: none;
    }

    [data-theme='blueprint'] .kp-footer a:hover,
    [data-theme='blueprint'] .kp-footer a:focus-visible {
        color: var(--foreground);
    }

    /* ── Badges, tags, status ──────────────────────────────────────────── */

    [data-theme='blueprint'] .kp-badge,
    [data-theme='blueprint'] .kp-tag {
        border-radius: 2px;
        border: 1px solid var(--border-strong);
        font-family: var(--theme-font-mono);
