    /* ── Text shapes: identifiers in mono ──────────────────────────────── */

    [data-theme='blueprint'] .kp-id,
    [data-theme='blueprint'] .kp-url,
    [data-theme='blueprint'] .kp-numeric,
    [data-theme='blueprint'] .kp-timestamp,
    [data-theme='blueprint'] .kp-masked,
    [data-theme='blueprint'] .kp-copyable,
    [data-theme='blueprint'] .kp-truncate,
    [data-theme='blueprint'] .kp-cell-break,
    [data-theme='blueprint'] .kp-cell-truncate {
        font-family: var(--theme-font-mono);
        font-size: 0.92em;
        letter-spacing: 0.02em;
    }

    [data-theme='blueprint'] .kp-copyable__button {
        border: 1px solid var(--border-strong);
        border-radius: 2px;
    }

    /* The copy button's two states win over this register's own button
       rules [gap-12]: those paint in kp.register, which beats the states
       in kp.components, so copied lost its success plate and a refused
       copy looked idle. Restated token for token. */
    [data-theme='blueprint'] .kp-copyable .kp-copyable__button[data-kp-copied] {
        border-color: var(--success);
        color: var(--success-foreground);
        background: var(--success);
    }

    [data-theme='blueprint'] .kp-copyable .kp-copyable__button[data-kp-copy-failed] {
        border-color: var(--destructive);
        border-style: dashed;
        color: var(--destructive);
    }

    /* ── Data: hairline tables and panels ─────────────────────────────── */

    [data-theme='blueprint'] .kp-table th {
        background: var(--card);
        /* The reach above a sticky header paints this ground too [fix-32]. */
        --kp-datatable-head-ground: var(--card);
        border-block-end: 1px solid var(--border-strong);
        font-weight: 600;
    }

    [data-theme='blueprint'] .kp-table td {
        border-block-end: 1px solid var(--border);
    }

    [data-theme='blueprint'] .kp-datatable {
        border: 1px solid var(--border-strong);
        border-radius: 2px;
        background: var(--card);
    }

    [data-theme='blueprint'] .kp-datatable__bar {
        background: var(--background);
        border-block-end: 1px solid var(--border);
    }

    [data-theme='blueprint'] .kp-datatable__sort[aria-sort] {
        color: var(--primary);
    }

    [data-theme='blueprint'] .kp-diff {
        background: var(--card);
        border: 1px solid var(--border-strong);
        border-radius: 2px;
        font-family: var(--theme-font-mono);
    }

    [data-theme='blueprint'] .kp-timeline {
        border-inline-start: 1px solid var(--border-strong);
    }

    [data-theme='blueprint'] .kp-timeline__marker {
        background: var(--primary);
        border-radius: 999px;
    }

    [data-theme='blueprint'] .kp-tree {
        font-family: var(--theme-font-mono);
        font-size: 0.9rem;
    }

    /* The accordion [gap-12]: the drafting mono its category toggle and tree use. */
    [data-theme='blueprint'] .kp-accordion__summary {
        font-family: var(--theme-font-mono);
        font-size: 0.9rem;
    }

    [data-theme='blueprint'] .kp-accordion__summary::marker {
        color: var(--primary);
    }

    [data-theme='blueprint'] .kp-accordion__item[open] > .kp-accordion__summary {
        color: var(--primary);
    }

    [data-theme='blueprint'] .kp-reorder {
        border: 1px solid var(--border-strong);
        border-radius: 2px;
        background: var(--card);
    }

    /* ── Navigation and steps ──────────────────────────────────────────── */

    [data-theme='blueprint'] .kp-tab {
        color: var(--muted-foreground);
        border-block-end: 1px solid transparent;
    }

    [data-theme='blueprint'] .kp-tab[aria-selected='true'] {
        color: var(--foreground);
        border-block-end-color: var(--primary);
        font-weight: 600;
    }

    [data-theme='blueprint'] .kp-tabs__list {
        border-block-end: 1px solid var(--border);
    }

    [data-theme='blueprint'] .kp-breadcrumb,
    [data-theme='blueprint'] .kp-pagination {
        font-family: var(--theme-font-mono);
    }

    [data-theme='blueprint'] .kp-pagination a[aria-current],
    [data-theme='blueprint'] .kp-pagination [aria-current] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: 2px;
    }

    [data-theme='blueprint'] .kp-wizard {
        background: var(--card);
        border: 1px solid var(--border-strong);
        border-radius: 2px;
    }

    [data-theme='blueprint'] .kp-wizard__steps {
        font-family: var(--theme-font-mono);
        font-size: 0.85rem;
    }

    /* ── Pickers and palettes ─────────────────────────────────────────── */

    [data-theme='blueprint'] .kp-datepicker__day[aria-selected='true'] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: 2px;
    }

    [data-theme='blueprint'] .kp-colorpicker__swatch {
        border: 1px solid var(--border-strong);
        border-radius: 2px;
    }

    [data-theme='blueprint'] .kp-colorpicker__value {
        font-family: var(--theme-font-mono);
    }

    [data-theme='blueprint'] .kp-shortcuts__row kbd {
        font-family: var(--theme-font-mono);
        border: 1px solid var(--border-strong);
        border-radius: 2px;
        background: var(--card);
        padding-inline: 0.4em;
    }

    /* ── The roots the rules above reach only by their parts ──────────── */

    [data-theme='blueprint'] .kp-combobox,
    [data-theme='blueprint'] .kp-datepicker,
    [data-theme='blueprint'] .kp-colorpicker,
    [data-theme='blueprint'] .kp-shortcuts,
    [data-theme='blueprint'] .kp-tabs {
        border-radius: 2px;
    }

    [data-theme='blueprint'] .kp-field {
        gap: calc(var(--kp-space-xs) * 1.2);
    }

    [data-theme='blueprint'] .kp-form {
        gap: calc(var(--kp-space-lg) * 0.85);
    }

    [data-theme='blueprint'] .kp-grid {
        gap: 1.25rem;
    }

    [data-theme='blueprint'] .kp-health {
        color: var(--muted-foreground);
        font-family: var(--theme-font-mono);
    }

    /* The spec sheet: a flat card, hairline-bounded, no shadow — the
       "sleek" mandate applied past the headline to the rest of the
       surface furniture. */
    [data-theme='blueprint'] .kp-spec {
        background: var(--card);
        border: 1px solid var(--border-strong);
        border-radius: 2px;
    }

    [data-theme='blueprint'] .kp-split {
        gap: 0;
    }

    [data-theme='blueprint'] .kp-table {
        border-collapse: separate;
        border-spacing: 0;
        background: var(--card);
    }

    [data-theme='blueprint'] .kp-toasts {
        gap: 0.5rem;
    }

    /* ── Motion, guarded [DI5, DI7] ────────────────────────────────────── */

    /* Every animation and transition of this register lives here, inside
       the no-preference guard, so a reader who asked for reduced motion
       never receives one: the rest states above are what they get. The
       durations are literal because check-motion.mjs computes DI5's rate
       from them; the matching TIMINGS rows are what js/effects.js and the
       DI5 report read. */
    @media (prefers-reduced-motion: no-preference) {
        /* The headline settles in behind the two dimension lines the
           moment the module arms the page — gated on `[data-kp-effects]`
           alone, never a class this module toggles, because the headline
           text itself is never touched (see the header comment). */
        [data-theme='blueprint'] [data-kp-surface='hero'] h1[data-kp-reveal='headline'] {
            opacity: 0;
            transform: translateY(6px);
        }

        [data-theme='blueprint'][data-kp-effects] [data-kp-surface='hero'] h1[data-kp-reveal='headline'] {
            animation: kp-headline-fade 300ms ease-out 600ms both;
        }

        /* The frame arrives after the headline has settled: the brackets
           together, the readout behind them. Two animations where the two
           dimension lines needed four. */
        [data-theme='blueprint'][data-kp-effects] [data-kp-measure-bracket] {
            animation: kp-dim-label 300ms ease-out 1000ms both;
        }

        [data-theme='blueprint'][data-kp-effects] [data-kp-measure] {
            animation: kp-dim-label 300ms ease-out 1300ms both;
        }

        [data-theme='blueprint'] [data-kp-reveal='rule'].is-in::after {
            animation: kp-rule-in 420ms ease-out both;
        }

        [data-theme='blueprint'] mark {
            transition: background-size 500ms ease-out;
        }

        /* The redactions: the ink block narrows away from the left,
           staggered 150ms apart — a size, not a colour cross-fade, so no
           mid-transition shade is ever legible [KT8]. The words take their
           ink in no time once their block is gone, because the block is a
           different colour from the words it hides. */
        [data-theme='blueprint'] .kp-card[data-kp-reveal='emphasis'] mark {
            transition:
                background-size 400ms ease-out,
                color 0s linear;
        }

        [data-theme='blueprint'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(2) {
            transition-delay: var(--kp-redact-stagger), 0s;
        }

        [data-theme='blueprint'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(3) {
            transition-delay: calc(2 * var(--kp-redact-stagger)), 0s;
        }

        /* Opened, each phrase's words wait for its own block to go; covered
           again, they go at once, before the block grows. */
        [data-theme='blueprint'] .kp-card[data-kp-reveal='emphasis'] mark.is-cleared {
            transition-delay: 0s, 400ms;
        }

        [data-theme='blueprint'] .kp-card[data-kp-reveal='emphasis'] mark.is-cleared:nth-of-type(2) {
            transition-delay: var(--kp-redact-stagger), calc(400ms + var(--kp-redact-stagger));
        }

        [data-theme='blueprint'] .kp-card[data-kp-reveal='emphasis'] mark.is-cleared:nth-of-type(3) {
            transition-delay: calc(2 * var(--kp-redact-stagger)), calc(400ms + 2 * var(--kp-redact-stagger));
        }
    }

    /* ── Motion [DI5, DI7] ────────────────────────────────────────────── */

    /* Every keyframe here has its row in TIMINGS (js/effects.js);
       kp-rule-in is the base layer's. Each is a single pass, once. */
    @keyframes kp-headline-fade {
        0% {
            opacity: 0;
            transform: translateY(6px);
        }

        100% {
            opacity: 1;
            transform: translateY(0);
        }
    }

    @keyframes kp-dim-label {
        0% {
            opacity: 0;
        }

        100% {
            opacity: 1;
        }
    }

    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — the cyan top rule of a title block, mono in caps. */
    [data-theme='blueprint'] .kp-marquee {
        border-block-start: 2px solid var(--primary);
        border-block-end: 1px solid var(--border);
        font-family: var(--theme-font-mono);
        letter-spacing: 0.1em;
        text-transform: uppercase;
        --kp-marquee: 34000ms;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    /* A mega menu's group headings speak in the caption's voice [scope-48]. */
    [data-theme='blueprint'] .kp-nav__menu[data-kp-menu-label]::before,
    [data-theme='blueprint'] .kp-nav__menu--wide .kp-nav__menu-heading {
        color: var(--primary);
        font-family: var(--theme-font-mono);
        letter-spacing: 0.12em;
        border-block-end: 1px dashed var(--border);
    }

    /* ── The side navigation [feat-nav-3] ────────────────────────────
       A drawing's index. Every row is a callout, and the one you are on
       carries the leader line and the tick that this theme draws beside
       anything it is pointing at. */
    [data-theme='blueprint'] .kp-sidenav {
        --kp-sidenav-surface: var(--card);
        --kp-sidenav-gap: 0;
        border-inline-end: 1px solid var(--border-strong);
    }

    [data-theme='blueprint'] .kp-sidenav__title {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.2em;
        text-transform: uppercase;
    }

    [data-theme='blueprint'] .kp-sidenav__link,
    [data-theme='blueprint'] .kp-sidenav__category-toggle {
        border-radius: 0;
        padding-inline-start: 1.5rem;
        font-family: var(--theme-font-mono);
    }

    [data-theme='blueprint'] .kp-sidenav__link::before {
        content: '';
        position: absolute;
        inset-inline-start: 0.5rem;
        inset-block-start: 50%;
        inline-size: 0.5rem;
        block-size: 1px;
        background: var(--border-strong);
        opacity: 0;
    }

    [data-theme='blueprint'] .kp-sidenav__link[aria-current='page'] {
        color: var(--foreground);
        background: none;
        border-inline-start: 1px solid var(--border-strong);
    }

    [data-theme='blueprint'] .kp-sidenav__link[aria-current='page']::before,
    [data-theme='blueprint'] .kp-sidenav__link:hover::before {
        opacity: 1;
    }

    /* ── Back to top, and a picture [feat-page-1, feat-media-1] ──────
       A picture on a drawing is a detail view: ruled, cornered, and
       captioned in the mono face the sheet is annotated in. */
    [data-theme='blueprint'] .kp-to-top {
        border-radius: 0;
        border: 1px solid var(--border-strong);
        font-family: var(--theme-font-mono);
    }

    [data-theme='blueprint'] .kp-media {
        border: 1px solid var(--border-strong);
        border-radius: 0;
        outline: 1px solid var(--border);
        outline-offset: 3px;
    }

    [data-theme='blueprint'] .kp-media-figure > figcaption {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.08em;
    }

    /* The figure carries the caption's voice, so the decision sits with
       the picture rather than with the words under it. */
    [data-theme='blueprint'] .kp-media-figure {
        color: var(--muted-foreground);
    }

    /* ── The pressed state the register had been cancelling [fix-12] ───
       `kp.register` sits after `kp.components`, and a layer beats a state:
       a register writing `.kp-button:hover { background: ... }` outranks
       the base layer's `.kp-button:active`, so pressing the button changed
       nothing. Kenny found it on shade-dark, 2026-09-11 — "als ik gewoon
       blijf klikken op de knop zelf, dan gebeurt er precies niks" — and
       fifteen of the twenty-five registers had it.

       These restate the base layer's own pressed values, token for token.
       Nothing new is decided here; what the components layer already said
       is put back where the cascade can reach it. */

    [data-theme='blueprint'] .kp-button:active:not(:disabled) {
        background: var(--secondary-active);
    }

    [data-theme='blueprint'] .kp-button--primary:active:not(:disabled) {
        background: var(--primary-active);
        border-color: var(--primary-active);
    }

    [data-theme='blueprint'] .kp-button--destructive:active:not(:disabled) {
        background: var(--destructive-active);
        border-color: var(--destructive-active);
    }

    /* ── The dimension witness [gap-4, approved 2026-09-12] ────────────
       A technical drawing calls out a length with two witness lines at its
       ends. Touching a control sets them beside it, in the amber this
       theme already reserves for its call-outs — the control becomes a
       measured length for as long as you are on it.

       The same instrument as the measurement frame this register took from
       the command table in round six: four corner brackets reporting the
       box they hold. This is that tool on a smaller thing.

       Outside the control, so the box does not move: measured in firefox
       2026-09-12, unchanged at rest and hovered, label contrast 9.33. */
    [data-theme='blueprint'] .kp-button::before,
    [data-theme='blueprint'] .kp-button::after {
        content: '';
        position: absolute;
        inset-block: calc(-1 * var(--kp-witness-overhang, 0.4rem));
        inline-size: 1px;
        background: var(--accent);
        opacity: 0;
        pointer-events: none;
    }

    /* Phase 7, `blueprint-lines`, Kenny 2026-09-12: "De lijntjes komen
       naar binnen". The witness lines stood at `-0.35rem` OUTSIDE the
       control, and the right-hand one therefore added 5.6px plus its own
       pixel to every blueprint button's scrollable area, visible or not —
       measured `195 in 189`, `194 in 188`, `190 in 184`, `166 in 160`,
       `114 in 108` on the concept page, the same six pixels every time.
       `overflow: clip` with a clip margin was tried and does not help:
       firefox counts the clip margin in `scrollWidth`.

       So the gap changes sign. The lines now sit the same distance from
       the boundary, on the inside of it, and the control no longer
       carries six pixels nobody can reach. The vertical overhang is
       untouched — it never contributed to the width, and it is what makes
       them read as measurement marks rather than as a border. */
    [data-theme='blueprint'] .kp-button::before {
        inset-inline-start: var(--kp-witness-gap, 0.35rem);
    }

    [data-theme='blueprint'] .kp-button::after {
        inset-inline-end: var(--kp-witness-gap, 0.35rem);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='blueprint'] .kp-button::before,
        [data-theme='blueprint'] .kp-button::after {
            transition: opacity var(--fx-duration, 180ms) var(--fx-ease, ease);
        }
    }

    [data-theme='blueprint'] .kp-button:hover:not(:disabled)::before,
    [data-theme='blueprint'] .kp-button:hover:not(:disabled)::after,
    [data-theme='blueprint'] .kp-button:focus-visible::before,
    [data-theme='blueprint'] .kp-button:focus-visible::after {
        opacity: 1;
    }

    /* ── Read-only fields [gap-11] ────────────────────────────────────── */

    /* A read-only field is a value on a record, not a box to type in. This
       register sets the field's border and ground in kp.register, which
       beats the read-only look in kp.components, so read-only painted like
       an editable field. The state is answered here, on top of the rest
       look, which stays as it was. */
    [data-theme='blueprint'] .kp-field__input[readonly] {
        border-style: dashed;
        background-color: var(--muted);
    }

    /* ── The palette's trigger in the bar [scope-48, scope-80] ─────────── */

    /* In the voice of this register's own nav links (Kenny, 2026-09-14,
       search-voice "Per thema"): muted drafting text with no plate, a
       hairline that inks in under it when pointed at or focused. The link's
       typeface, case, spacing, shape and pointer answer are restated here,
       because the trigger is a button beside the list rather than a link in
       it. The underline a plain link carries is not: it says "this is a
       link", and the trigger is not one. */
    [data-theme='blueprint'] .kp-nav__search .kp-nav__search-trigger {
        padding-inline: 0;
        border: 0;
        border-block-end: 1px solid transparent;
        border-radius: 0;
        background: none;
        color: var(--muted-foreground);
    }

    [data-theme='blueprint'] .kp-nav__search .kp-nav__search-trigger:hover,
    [data-theme='blueprint'] .kp-nav__search .kp-nav__search-trigger:focus-visible {
        color: var(--foreground);
        border-block-end-color: var(--border-strong);
    }

    /* ── The alarm [scope-94] ──────────────────────────────────────────────
       A red line on the drawing: the plate is its deep blue, the frame a cyan dashed construction line, and a drafting grid replaces the scanlines. Every colour is one of this theme's tokens. The
       button keeps this register's shape and takes the alarm's paint, on
       selectors long enough to outrank this register's own button states;
       the dialog takes no focus ring, because in the auto mode the whole
       screen is what has focus. */
    [data-theme='blueprint'] .kp-alarm {
        --kp-alarm-ground: hsl(from var(--background) h s 8% / 0.96);
        --kp-alarm-ink: hsl(from var(--destructive) h s max(l, 64));
        --kp-alarm-soft: var(--foreground);
        --kp-alarm-split: var(--primary);
        --kp-alarm-on-ink: hsl(from var(--background) h s 8%);
        --kp-alarm-glow: hsl(from var(--destructive) h s 50 / 0.35);
        --kp-alarm-halo: hsl(from var(--destructive) h s 50 / 0.4);
        --kp-alarm-scan: hsl(from var(--primary) h s l / 0.08);
        --kp-alarm-vignette: hsl(from var(--background) h s 3% / 0.7);
        --kp-alarm-frame: 1px dashed var(--primary);
    }

    [data-theme='blueprint'] .kp-alarm:focus-visible {
        outline: none;
    }

    [data-theme='blueprint'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack,
    [data-theme='blueprint'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:hover:not(:disabled),
    [data-theme='blueprint'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:active:not(:disabled) {
        border-color: var(--kp-alarm-ink);
        background: var(--kp-alarm-ink);
        color: var(--kp-alarm-on-ink);
