    [data-theme='blueprint'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep,
    [data-theme='blueprint'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep:is(:hover, :focus-visible):not(:disabled) {
