        opacity: 1;
        translate: 0 0;
    }

    [data-theme='dark'] .kp-button__edge {
        inset-block-start: auto;
        block-size: 2px;
        background: var(--kp-iris);
        scale: 0 1;
        transform-origin: left center;
        z-index: 1;
    }

    [data-theme='dark'] .kp-button:hover:not(:disabled, [aria-disabled='true']) .kp-button__edge,
    [data-theme='dark'] .kp-button:focus-visible .kp-button__edge {
        scale: 1 1;
    }

    [data-theme='dark'] .kp-button__label {
        position: relative;
        z-index: 2;
    }

    [data-theme='dark'] .kp-button:hover:not(:disabled, [aria-disabled='true']) .kp-button__label,
    [data-theme='dark'] .kp-button:focus-visible .kp-button__label {
        scale: 0.94;
    }

