        color: var(--primary-foreground);
    }

    [data-theme='dark'] .kp-wizard {
        border: 1px solid var(--border-strong);
        background: var(--card);
    }

    /* ── Pickers and palettes ─────────────────────────────────────────── */

    [data-theme='dark'] .kp-datepicker__day[aria-selected='true'] {
