        color: var(--foreground);
        background: var(--secondary);
    }

    /* ── Buttons ───────────────────────────────────────────────────────── */

    [data-theme='shade-dark'] .kp-button,
    [data-theme='shade-dark'] .kp-icon-button {
        background: var(--secondary);
        color: var(--secondary-foreground);
        border: 1px solid transparent;
        border-radius: var(--radius);
        font-weight: 600;
    }

    [data-theme='shade-dark'] .kp-button:hover {
        background: hsl(from var(--secondary) h s calc(l + 4));
    }

    [data-theme='shade-dark'] .kp-button--primary {
        background: var(--primary);
        color: var(--primary-foreground);
    }

    [data-theme='shade-dark'] .kp-button--primary:hover {
        background: hsl(from var(--primary) h s calc(l + 7));
    }

    [data-theme='shade-dark'] .kp-button--ghost {
        background: transparent;
        color: var(--foreground);
        border-color: var(--border-strong);
    }

    [data-theme='shade-dark'] .kp-button--ghost:hover {
        background: var(--card);
    }

    [data-theme='shade-dark'] .kp-button--destructive {
        background: var(--destructive);
        color: var(--destructive-foreground);
    }

    [data-theme='shade-dark'] .kp-button--destructive:hover {
        background: hsl(from var(--destructive) h s calc(l + 8));
    }

    [data-theme='shade-dark'] .kp-button:disabled {
        opacity: 0.55;
    }

    /* The demo's call-to-action row: wide buttons, as in the reference. A
       pager's or a menu's button keeps its own width (DI11 at 320 px). */
    [data-theme='shade-dark'] [data-kp-surface='hero'] .kp-row > .kp-button {
        min-width: min(11rem, 100%);
    }

    /* ── Fields ────────────────────────────────────────────────────────── */

    [data-theme='shade-dark'] .kp-field__label {
        font-weight: 600;
    }

    [data-theme='shade-dark'] .kp-field__required {
        font-weight: 400;
        color: var(--muted-foreground);
    }

    [data-theme='shade-dark'] .kp-field__input,
    [data-theme='shade-dark'] .kp-datatable__search,
    [data-theme='shade-dark'] .kp-combobox__input,
    [data-theme='shade-dark'] .kp-palette__input {
        background: var(--card);
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
    }

    [data-theme='shade-dark'] .kp-field__help {
        color: var(--muted-foreground);
    }

    [data-theme='shade-dark'] .kp-field--invalid .kp-field__input {
        border-color: var(--destructive);
    }

    [data-theme='shade-dark'] .kp-field__error {
        color: var(--destructive);
    }

    [data-theme='shade-dark'] .kp-field__check {
        accent-color: var(--primary);
    }

    [data-theme='shade-dark'] .kp-fieldset {
        border: 1px solid var(--border);
        border-radius: var(--radius);
    }

    /* The switch [gap-11]: the pill, on the card as the inputs are. */
    [data-theme='shade-dark'] .kp-switch {
        --kp-switch-radius: var(--kp-radius-pill, 999px);
    }

    [data-theme='shade-dark'] .kp-switch__input:not(:checked) {
        background: var(--card);
    }

    [data-theme='shade-dark'] .kp-form__summary {
        background: var(--card);
        border: 1px solid var(--border);
        border-radius: var(--radius);
    }

    /* ── Cards, popovers and surfaces: the tone ladder alone, no shadow ─── */

    [data-theme='shade-dark'] .kp-card,
    [data-theme='shade-dark'] .kp-popover {
        background: var(--card);
        border: 1px solid var(--border);
        border-radius: var(--radius);
        box-shadow: none;
    }

    [data-theme='shade-dark'] .kp-card__stamp {
        font-family: var(--theme-font-mono);
        font-size: 0.68rem;
        text-transform: uppercase;
        letter-spacing: 0.1em;
        color: var(--status-draft-foreground);
        background: var(--status-draft);
        border-radius: 0.2rem;
    }

