        border-radius: var(--radius) var(--radius) 0 0;
    }

    [data-theme='shade-dark'] .kp-tab[aria-selected='true'] {
        color: var(--foreground);
        border-bottom: 2px solid var(--accent);
    }

    [data-theme='shade-dark'] .kp-tabs__list {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='shade-dark'] .kp-breadcrumb {
        color: var(--muted-foreground);
    }

    [data-theme='shade-dark'] .kp-pagination {
        color: var(--muted-foreground);
    }

    [data-theme='shade-dark'] .kp-pagination a[aria-current],
    [data-theme='shade-dark'] .kp-pagination [aria-current] {
