    }

    [data-theme='shade-dark'] .kp-colorpicker__swatch {
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
    }

    [data-theme='shade-dark'] .kp-shortcuts__row kbd {
        border: 1px solid var(--border-strong);
        border-radius: 0.2rem;
        background: var(--card);
        font-family: var(--theme-font-mono);
    }

    /* ── The roots the rules above reach only by their parts ────────────── */

    [data-theme='shade-dark'] .kp-combobox,
    [data-theme='shade-dark'] .kp-datepicker,
    [data-theme='shade-dark'] .kp-colorpicker,
    [data-theme='shade-dark'] .kp-shortcuts,
    [data-theme='shade-dark'] .kp-tabs {
        border-radius: var(--radius);
    }

    [data-theme='shade-dark'] .kp-field {
        gap: calc(var(--kp-space-xs) * 1.4);
    }

    [data-theme='shade-dark'] .kp-form {
        gap: calc(var(--kp-space-lg) * 1.1);
    }

    [data-theme='shade-dark'] .kp-split {
        gap: 0;
    }

    /* ── The scrollbar joins the theme ──────────────────────────────────── */

    [data-theme='shade-dark'] {
        scrollbar-color: var(--border-strong) var(--card);
    }

    /* ── The demo's own pieces [S46] ─────────────────────────────────────── */

    [data-theme='shade-dark'] .kp-side-note {
        font-family: var(--theme-font-mono);
        font-size: 0.72rem;
        letter-spacing: 0.14em;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    [data-theme='shade-dark'] .kp-laurels {
        color: var(--muted-foreground);
    }

    [data-theme='shade-dark'] .kp-laurels b {
        color: var(--foreground);
    }

    [data-theme='shade-dark'] .kp-lede {
        max-width: 42rem;
    }

    [data-theme='shade-dark'] .kp-platforms {
        font-family: var(--theme-font-mono);
        font-size: 0.78rem;
        color: var(--muted-foreground);
    }

    [data-theme='shade-dark'] .kp-platforms span::before {
        content: '· ';
        color: var(--border-strong);
    }

    [data-theme='shade-dark'] .kp-platforms span:first-child::before {
        content: '';
    }

    [data-theme='shade-dark'] .kp-spec {
        background: var(--card);
        border: 1px solid var(--border);
        border-radius: var(--radius);
    }

    [data-theme='shade-dark'] .kp-spec dt {
        color: var(--muted-foreground);
    }

    [data-theme='shade-dark'] .kp-spec__swatch {
        border: 1px solid var(--border-strong);
        border-radius: 0.25rem;
    }

    [data-theme='shade-dark'] .kp-spec__font {
        font-family: var(--theme-font-display);
    }

    /* ── Motion, guarded [DI7] ─────────────────────────────────────────── */

    /* Every animation and transition of this register lives here, inside
       the no-preference guard, so a reader who asked for reduced motion
       never receives one: the rest states above (rule drawn, mark plain,
       card and button in full focus) are what they get. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='shade-dark'] [data-kp-reveal='headline'].is-words [data-word] {
            animation: kp-focus 600ms var(--kp-ease-reveal) both;
            animation-delay: calc(var(--kp-i, 0) * var(--kp-word-stagger));
        }

        [data-theme='shade-dark'] [data-kp-reveal='rule']::after {
            transition: transform 500ms var(--kp-ease-reveal);
        }

        /* The emphasis containers with nothing to clear settle out of the
           blur once, on load (see the finding above the rest-state rule). */
        [data-theme='shade-dark'][data-kp-effects] [data-kp-reveal='emphasis'] {
            animation: kp-focus 500ms var(--kp-ease-reveal) both;
        }

        [data-theme='shade-dark'] .kp-card[data-kp-reveal='emphasis'] mark::after {
            transition: transform 300ms var(--kp-ease-reveal);
        }

        [data-theme='shade-dark'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(2)::after {
            transition-delay: var(--kp-redact-stagger);
        }

        [data-theme='shade-dark'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(3)::after {
            transition-delay: calc(2 * var(--kp-redact-stagger));
        }

        /* The colour switches the instant the plate starts to recede: the
           text sits behind the plate at that moment, so nothing is ever
           read mid-transition (KT8). */
        [data-theme='shade-dark'] .kp-card[data-kp-reveal='emphasis'] mark {
            transition: color 0s linear 0s;
        }

        /* The dialog: opacity and a small settle, 180ms — the same
           --fx-duration this theme already ships (demo comment 2). */
        [data-theme='shade-dark'] .kp-dialog {
            animation: kp-dialog-in 180ms var(--fx-ease) both;
        }

        [data-theme='shade-dark'] .kp-dialog::backdrop {
            animation: kp-backdrop-in 180ms var(--fx-ease) both;
        }

        [data-theme='shade-dark'] .kp-button,
        [data-theme='shade-dark'] .kp-nav__link,
        [data-theme='shade-dark'] .kp-nav__link--cta,
        [data-theme='shade-dark'] .kp-nav__menu a,
        [data-theme='shade-dark'] .kp-footer a,
        [data-theme='shade-dark'] .kp-skip-link {
            transition:
                background var(--fx-duration) var(--fx-ease),
                border-color var(--fx-duration) var(--fx-ease),
                color var(--fx-duration) var(--fx-ease),
                opacity var(--fx-duration) var(--fx-ease),
                transform var(--fx-duration) var(--fx-ease),
                visibility var(--fx-duration) var(--fx-ease);
        }

        /* The same list for the dropdown, with the package's closing half
           restated: `display … allow-discrete` keeps the panel displayed
           while it fades out. The list above replaced the package's, and
           the panel was display: none from the first frame of closing
           [scope-100]. */
        [data-theme='shade-dark'] .kp-nav__menu {
            transition:
                background var(--fx-duration) var(--fx-ease),
                border-color var(--fx-duration) var(--fx-ease),
                color var(--fx-duration) var(--fx-ease),
                opacity var(--fx-duration) var(--fx-ease),
                transform var(--fx-duration) var(--fx-ease),
                visibility var(--fx-duration) var(--fx-ease),
                display var(--fx-duration) allow-discrete;
        }
    }

    /* ── Motion [DI5, DI7] ────────────────────────────────────────────── */

    /* Every keyframe here has its row in TIMINGS (js/effects.js). The
       headline's words and the emphasis containers' entrance are the same
       blur-and-focus device at two grains, one keyframe (kp-focus) at two
       durations; the dialog's pair is opacity
       with a small settle, once, on open. */
    @keyframes kp-focus {
        0% {
            opacity: 0;
            filter: blur(6px);
        }

        100% {
            opacity: 1;
            filter: blur(0);
        }
    }

    @keyframes kp-dialog-in {
        0% {
            opacity: 0;
            transform: translateY(6px) scale(0.98);
        }

        100% {
            opacity: 1;
            transform: none;
        }
    }

    @keyframes kp-backdrop-in {
        0% {
            opacity: 0;
        }

        100% {
            opacity: 1;
        }
    }
    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — the same fade in the dark. */
    [data-theme='shade-dark'] .kp-marquee {
        mask-image: linear-gradient(90deg, transparent, black 12%, black 88%, transparent);
        color: var(--muted-foreground);
        font-family: var(--theme-font-mono);
        --kp-marquee: 46000ms;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    /* A mega menu's group headings speak in the caption's voice [scope-48]. */
    [data-theme='shade-dark'] .kp-nav__menu[data-kp-menu-label]::before,
    [data-theme='shade-dark'] .kp-nav__menu--wide .kp-nav__menu-heading {
        font-family: var(--theme-font-mono);
        text-transform: none;
        letter-spacing: 0;
        color: var(--muted-foreground);
        border-block-end: 0;
    }

    /* ── The side navigation [feat-nav-3] ────────────────────────────
       Kenny called this one sober too, and its answer is its twin's read
       the other way round: light falls from above onto a dark ground, so
       the row you are on is the one CUT INTO the panel rather than lifted
       off it. */
    [data-theme='shade-dark'] .kp-sidenav {
        --kp-sidenav-surface: var(--card);
        --kp-sidenav-gap: 0.25rem;
        border: 1px solid var(--border);
        border-radius: var(--radius);
    }

    [data-theme='shade-dark'] .kp-sidenav__link,
    [data-theme='shade-dark'] .kp-sidenav__category-toggle {
        border-radius: var(--radius);
    }

    [data-theme='shade-dark'] .kp-sidenav__link[aria-current='page'] {
        background: var(--background);
        color: var(--foreground);
        box-shadow:
            inset 0 1px 3px hsl(from var(--background) h s l / 0.9),
            inset 0 -1px 0 hsl(from var(--foreground) h s l / 0.12);
    }

    /* ── Back to top, and a picture [feat-page-1, feat-media-1] ──────
       Light from above onto a dark ground: the control is lifted, the
       frame is set into the page. */
    [data-theme='shade-dark'] .kp-to-top {
        box-shadow:
            inset 0 1px 0 hsl(from var(--foreground) h s l / 0.14),
            0 2px 8px hsl(from var(--background) h s l / 0.8);
    }

    [data-theme='shade-dark'] .kp-media {
        border: 1px solid var(--border);
        box-shadow: inset 0 1px 4px hsl(from var(--background) h s l / 0.9);
    }

    [data-theme='shade-dark'] .kp-media-figure > figcaption {
        color: var(--muted-foreground);
    }

    /* The figure carries the caption's voice, so the decision sits with
       the picture rather than with the words under it. */
    [data-theme='shade-dark'] .kp-media-figure {
        color: var(--muted-foreground);
    }

    /* ── The pressed state the register had been cancelling [fix-12] ───
       `kp.register` sits after `kp.components`, and a layer beats a state:
       a register writing `.kp-button:hover { background: ... }` outranks
       the base layer's `.kp-button:active`, so pressing the button changed
       nothing. Kenny found it on shade-dark, 2026-09-11 — "als ik gewoon
       blijf klikken op de knop zelf, dan gebeurt er precies niks" — and
       fifteen of the twenty-five registers had it.

       These restate the base layer's own pressed values, token for token.
       Nothing new is decided here; what the components layer already said
       is put back where the cascade can reach it. */

    [data-theme='shade-dark'] .kp-button:active:not(:disabled) {
        background: var(--secondary-active);
    }

    [data-theme='shade-dark'] .kp-button--primary:active:not(:disabled) {
        background: var(--primary-active);
        border-color: var(--primary-active);
    }

    [data-theme='shade-dark'] .kp-button--destructive:active:not(:disabled) {
        background: var(--destructive-active);
        border-color: var(--destructive-active);
    }

    /* ── One light, one direction [scope-12] ───────────────────────────
       shade-light's law, read on the other material. A single source at
       the top left: at rest the control lies on the surface, under the
       pointer it lifts and its shadow lengthens, pressed it goes BELOW
       the surface and the shadow turns inward.

       On a dark ground the shadow has to fall further and softer to be
       seen at all — 2px against the light twin's 1, blurred 5 against 3,
       and cast in the theme's own near-black rather than its text colour.
       Same law, different material, which is what makes the two a pair.

       Scoped off the button variants for the same reason shade-light is:
       the approved round-six demo draws them flat and its own test pins
       that. A finding for Kenny, not a decision taken here [S49].

       The source MOVES from scope-101 [scope-25, "the pointer is the
       light, and the light half throws its shade away from it while the
       dark half is LIFTED OUT of shade by it"]. Two things happen here
       that do not happen on the light half: the shadow's length is scaled
       by `--kp-light-lift` (0.6 at a distance, up to 1.6 under the
       pointer), and the surface nearest the pointer takes a pale wash of
       the ink centred on where the pointer sits inside its own box. The
       wash is the lifting; the shadow under it is the ground, darkened,
       because a shadow in --background on --background is invisible.
       Implemented as research/scope25-gestures/demo.html draws it, patch
       sizes included — 8% on a button, 6% on a card and the hero, where a
       9% card patch measured 4.37 against the card text and was cut. */
    /* Phase 7, `focus-ring`. The rule below paints this theme's own
       elevation on a button, and it is a later layer than kp.components,
       so it swallowed the ring that layer draws on `:focus-visible` — a
       keyboard user got an outline and nothing behind it. Measured
       before: `color(srgb 0 0.176 0.22 / 0.9) 2px 3px 5px`. That is the theme's elevation, not the ring.

       The elevation stays; what is added is the ring in front of it, in
       the focused state only, spelled the way css/components.css spells
       it. Third face of the same fault as `fix-12` and `gap-1`: a later
       layer beating a state the earlier layer defines. */
    [data-theme='shade-dark'] .kp-button:not([class*='kp-button--']) {
        box-shadow: calc(var(--kp-light-x, 1) * var(--kp-light-lift, 1) * 2px) calc(var(--kp-light-y, 1) * var(--kp-light-lift, 1) * 3px) 5px
            hsl(from var(--background) h s l / 0.9);
        background-image: radial-gradient(
            circle 8rem at var(--kp-light-at-x, 0) var(--kp-light-at-y, 0),
            hsl(from var(--foreground) h s l / calc(var(--kp-light-near, 0) * 0.08)),
            transparent
        );
    }

