    .kp-gap-x-2xl {
        column-gap: var(--kp-space-2xl);
    }

    .kp-gap-y-0 {
        row-gap: 0;
    }

    .kp-gap-y-xs {
        row-gap: var(--kp-space-xs);
    }

    .kp-gap-y-sm {
        row-gap: var(--kp-space-sm);
    }

    .kp-gap-y-md {
        row-gap: var(--kp-space-md);
    }

    .kp-gap-y-lg {
        row-gap: var(--kp-space-lg);
    }

    .kp-gap-y-xl {
        row-gap: var(--kp-space-xl);
    }

    .kp-gap-y-2xl {
        row-gap: var(--kp-space-2xl);
    }

    /* Display — `.kp-d-grid` carries the `d-` prefix because `.kp-grid` is already the dashboard grid component. */
    .kp-d-block {
        display: var(--kp-d-block, block);
    }

    .kp-d-inline {
        display: var(--kp-d-inline, inline);
    }

    .kp-d-inline-block {
        display: var(--kp-d-inline-block, inline-block);
    }

    .kp-d-flex {
        display: var(--kp-d-flex, flex);
    }

    .kp-d-inline-flex {
        display: var(--kp-d-inline-flex, inline-flex);
    }

    .kp-d-grid {
        display: var(--kp-d-grid, grid);
    }

    .kp-d-none {
        display: var(--kp-d-none, none);
    }

    /* Flex and grid alignment — Works on a grid container too: both box models read these properties. */
    .kp-items-start {
        align-items: flex-start;
    }

    .kp-items-center {
        align-items: center;
    }

    .kp-items-end {
        align-items: flex-end;
    }

    .kp-items-stretch {
        align-items: stretch;
    }

    .kp-items-baseline {
        align-items: baseline;
    }

    .kp-justify-start {
        justify-content: flex-start;
    }

    .kp-justify-center {
        justify-content: center;
    }

    .kp-justify-end {
        justify-content: flex-end;
    }

    .kp-justify-between {
        justify-content: space-between;
    }

    .kp-justify-around {
        justify-content: space-around;
    }

    .kp-flex-row {
        flex-direction: row;
    }

    .kp-flex-column {
        flex-direction: column;
    }

    .kp-flex-wrap {
        flex-wrap: wrap;
    }

    .kp-flex-nowrap {
        flex-wrap: nowrap;
    }

    .kp-flex-1 {
        flex: 1 1 0%;
    }

    .kp-flex-auto {
        flex: 1 1 auto;
    }

    .kp-flex-none {
        flex: 0 0 auto;
    }

    .kp-self-start {
        align-self: flex-start;
    }

    .kp-self-center {
        align-self: center;
    }

    .kp-self-end {
        align-self: flex-end;
    }

    .kp-self-stretch {
        align-self: stretch;
    }

    /* Text — No `.kp-truncate`: css/components.css already declares it, with a display and a max-width this family would drop. The collision gate found that. The font-size family reads the three steps the components actually use; there are three rather than six because the scale has three, and inventing steps nothing uses would be inventing values. Alignment, the muted colour, the mono face and the prose measure are layout classes (TH91), not utilities. */
    .kp-fs-xs {
        font-size: var(--kp-text-xs);
    }

    .kp-fs-sm {
        font-size: var(--kp-text-sm);
    }

    .kp-fs-md {
        font-size: var(--kp-text-md);
    }

    .kp-fw-normal {
        font-weight: var(--kp-fw-normal, 400);
    }

    .kp-fw-medium {
        font-weight: var(--kp-fw-medium, 500);
    }

    .kp-fw-semibold {
        font-weight: var(--kp-fw-semibold, 600);
    }

    .kp-fw-bold {
        font-weight: var(--kp-fw-bold, 700);
    }

    .kp-tt-upper {
        text-transform: uppercase;
    }

    .kp-tt-lower {
        text-transform: lowercase;
    }

    .kp-tt-capitalize {
        text-transform: capitalize;
    }

    .kp-text-nowrap {
        white-space: nowrap;
    }

    .kp-text-balance {
        text-wrap: balance;
    }

    .kp-text-pretty {
        text-wrap: pretty;
    }

    .kp-lh-tight {
        line-height: var(--kp-lh-tight, 1.25);
    }

    .kp-lh-normal {
        line-height: var(--kp-lh-normal, 1.5);
    }

    .kp-lh-loose {
        line-height: var(--kp-lh-loose, 1.75);
    }

    /* Width and height — The three measures read the same knobs the layout containers do, so retuning `--kp-prose-max` moves both. */
    .kp-w-full {
        inline-size: 100%;
    }

    .kp-w-auto {
        inline-size: auto;
    }

    .kp-w-min {
        inline-size: min-content;
    }

    .kp-w-max {
        inline-size: max-content;
    }

    .kp-w-fit {
        inline-size: fit-content;
    }

    .kp-max-w-prose {
        max-inline-size: var(--kp-prose-max, 65ch);
    }

    .kp-max-w-center {
        max-inline-size: var(--kp-center-max, 28rem);
    }

    .kp-max-w-page {
        max-inline-size: var(--kp-page-max, 64rem);
    }

    .kp-h-full {
        block-size: 100%;
    }

    .kp-h-auto {
        block-size: auto;
    }
}
